/** Konten bab-dasar; dimuat hanya saat bab dibuka. */
export const BAGIAN = [{"id":"panduan-8","bab":"bab-dasar","nomor":"8","judul":"Apa Itu Skak, Skakmat, dan Stalemate dalam Catur? Penjelasan Lengkap untuk Pemula","deskripsi":"Memahami perbedaan antara skak, skakmat, dan stalemate adalah dasar yang wajib dikuasai dalam belajar catur. Ketiga kondisi ini menentukan arah dan hasil pertandingan secara langsung, sehingga pemahaman yang tepat terhadap ketiganya menjadi fondasi penting sebelum melangkah ke strategi yang lebih kompleks.","baris":[{"sub":false,"html":"<div class=\"content-row\">\n        <div class=\"text-content\">\n            <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">Skak, Skakmat, dan Stalemate: Tiga Kondisi Krusial dalam Permainan Catur</h3>\n            <p class=\"text-gray-600 leading-relaxed text-sm\">\n                Dalam permainan catur, terdapat tiga kondisi yang secara langsung menentukan apakah sebuah partai masih berlanjut, berakhir dengan kekalahan, atau berakhir tanpa pemenang. Ketiga kondisi tersebut adalah skak, skakmat, dan stalemate. Meskipun ketiganya berkaitan erat dengan posisi raja, masing-masing memiliki definisi, konsekuensi, dan implikasi strategis yang berbeda secara mendasar. Bagi pemula, memahami perbedaan di antara ketiganya bukan sekadar soal hafalan aturan, melainkan soal membangun kesadaran posisional yang menjadi dasar dari seluruh keputusan bermain.\n                <br><br>\n                Kerancuan antara ketiga kondisi ini kerap menjadi sumber kesalahan serius di meja pertandingan. Seorang pemain yang tidak memahami stalemate, misalnya, berisiko mengubah posisi menang menjadi hasil seri hanya karena satu langkah yang kurang diperhitungkan. Sebaliknya, pemain yang memahami skakmat secara mendalam akan mampu merancang tekanan yang terstruktur dan terarah, bukan sekadar menyerang tanpa tujuan yang jelas.\n            </p>\n        </div>\n    </div>"},{"sub":true,"html":"<div class=\"content-row\" style=\"margin-top: 2rem; padding-top: 1.5rem; border-top: 2px dashed #e5e7eb;\">\n        <div class=\"board-panel relative\" style=\"float: right; margin-left: 1.5rem; margin-bottom: 1rem;\">\n            <svg viewBox=\"0 0 200 220\" class=\"w-full h-full\">\n                <rect width=\"200\" height=\"200\" fill=\"#769656\"/>\n                <g fill=\"#eeeed2\">\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"0\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"25\"/>\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"50\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"75\"/>\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"100\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"125\"/>\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"150\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"175\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"175\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"175\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"175\"/>\n                </g>\n                <defs>\n                    <marker id=\"arrow-skak\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n                        <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#ef4444\"/>\n                    </marker>\n                    <marker id=\"arrow-escape\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n                        <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#22c55e\"/>\n                    </marker>\n                </defs>\n                <rect x=\"100\" y=\"0\" width=\"25\" height=\"25\" fill=\"#ef4444\" fill-opacity=\"0.5\"/>\n                <rect x=\"75\" y=\"0\" width=\"25\" height=\"25\" fill=\"#22c55e\" fill-opacity=\"0.4\"/>\n                <rect x=\"125\" y=\"0\" width=\"25\" height=\"25\" fill=\"#22c55e\" fill-opacity=\"0.4\"/>\n                <rect x=\"100\" y=\"0\" width=\"25\" height=\"200\" fill=\"#ef4444\" fill-opacity=\"0.08\"/>\n                <line x1=\"112.5\" y1=\"180\" x2=\"112.5\" y2=\"18\" stroke=\"#ef4444\" stroke-width=\"1.8\" stroke-dasharray=\"3,2\" marker-end=\"url(#arrow-skak)\"/>\n                <text x=\"112.5\" y=\"187.5\" font-size=\"18\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♖</text>\n                <text x=\"112.5\" y=\"12.5\" font-size=\"18\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\">♚</text>\n                <circle cx=\"122\" cy=\"4\" r=\"5\" fill=\"#ef4444\"/>\n                <text x=\"122\" y=\"4\" font-size=\"7\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" font-weight=\"bold\">!</text>\n                <line x1=\"107\" y1=\"12.5\" x2=\"92\" y2=\"12.5\" stroke=\"#22c55e\" stroke-width=\"1.5\" marker-end=\"url(#arrow-escape)\"/>\n                <line x1=\"118\" y1=\"12.5\" x2=\"133\" y2=\"12.5\" stroke=\"#22c55e\" stroke-width=\"1.5\" marker-end=\"url(#arrow-escape)\"/>\n                <text x=\"87.5\" y=\"209\" font-size=\"6.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">d8</text>\n                <text x=\"112.5\" y=\"209\" font-size=\"6.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">e8</text>\n                <text x=\"137.5\" y=\"209\" font-size=\"6.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">f8</text>\n                <text x=\"100\" y=\"218\" font-size=\"8\" fill=\"#ef4444\" text-anchor=\"middle\" font-weight=\"bold\">⚠ SKAK — Raja Masih Bisa Selamat</text>\n            </svg>\n            <div style=\"display:flex; gap:8px; margin-top:4px; justify-content:center; flex-wrap:wrap;\">\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#ef4444;border-radius:2px;display:inline-block;opacity:0.7\"></span> Raja diserang\n                </span>\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#22c55e;border-radius:2px;display:inline-block;opacity:0.7\"></span> Kotak kabur\n                </span>\n            </div>\n        </div>\n\n        <div class=\"text-content\">\n            <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">⚠️ Skak (Check)</h3>\n            <p class=\"text-gray-600 leading-relaxed text-sm\">\n                Skak adalah kondisi di mana raja seorang pemain berada dalam ancaman langsung dari bidak lawan. Ketika skak terjadi, seluruh prioritas permainan bergeser seketika — tidak ada langkah lain yang sah kecuali langkah yang secara langsung mengakhiri ancaman terhadap raja tersebut. Ini bukan sekadar tekanan psikologis, melainkan sebuah kewajiban hukum dalam permainan: selama raja berada dalam skak, pemain tidak diizinkan melakukan langkah apa pun yang membiarkan ancaman itu tetap ada.\n                <br><br>\n                Pada diagram di samping, benteng putih (♖) yang berdiri di <strong>e1</strong> melancarkan serangan vertikal langsung ke raja hitam di <strong>e8</strong>. Garis merah yang membentang di antara keduanya menggambarkan jalur ancaman yang aktif. Raja hitam berada dalam skak, namun masih memiliki ruang untuk bernapas: kotak <strong>d8</strong> dan <strong>f8</strong>, yang ditandai hijau, merupakan kotak-kotak aman yang dapat dijadikan tempat pelarian.\n                <br><br>\n                Secara umum, terdapat tiga jalur penyelamatan yang sah ketika raja berada dalam skak. Pertama, raja dapat dipindahkan ke kotak yang tidak berada dalam jangkauan serangan lawan. Kedua, jika jalur serangan memungkinkan, bidak lain dapat ditempatkan di antara raja dan penyerang untuk memutus ancaman. Ketiga, jika penyerang dapat dijangkau oleh bidak己方, bidak tersebut dapat menangkap penyerang secara langsung. Selama salah satu dari ketiga opsi ini tersedia, permainan belum berakhir — skak hanyalah sebuah titik tekanan, bukan vonis kekalahan.\n            </p>\n        </div>\n    </div>"},{"sub":true,"html":"<div class=\"content-row\" style=\"margin-top: 2rem; padding-top: 1.5rem; border-top: 2px dashed #e5e7eb;\">\n        <div class=\"board-panel relative\" style=\"float: left; margin-right: 1.5rem; margin-bottom: 1rem;\">\n            <svg viewBox=\"0 0 200 220\" class=\"w-full h-full\">\n                <rect width=\"200\" height=\"200\" fill=\"#769656\"/>\n                <g fill=\"#eeeed2\">\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"0\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"25\"/>\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"50\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"75\"/>\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"100\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"125\"/>\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"150\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"175\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"175\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"175\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"175\"/>\n                </g>\n                <defs>\n                    <marker id=\"arrow-mat1\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\">\n                        <path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#ef4444\"/>\n                    </marker>\n                </defs>\n                <rect x=\"175\" y=\"0\" width=\"25\" height=\"25\" fill=\"#ef4444\" fill-opacity=\"0.6\"/>\n                <rect x=\"150\" y=\"0\" width=\"25\" height=\"25\" fill=\"#dc2626\" fill-opacity=\"0.25\"/>\n                <rect x=\"150\" y=\"25\" width=\"25\" height=\"25\" fill=\"#dc2626\" fill-opacity=\"0.25\"/>\n                <rect x=\"175\" y=\"25\" width=\"25\" height=\"25\" fill=\"#dc2626\" fill-opacity=\"0.25\"/>\n                <rect x=\"175\" y=\"0\" width=\"25\" height=\"200\" fill=\"#ef4444\" fill-opacity=\"0.07\"/>\n                <line x1=\"187.5\" y1=\"178\" x2=\"187.5\" y2=\"18\" stroke=\"#ef4444\" stroke-width=\"1.8\" stroke-dasharray=\"3,2\" marker-end=\"url(#arrow-mat1)\"/>\n                <g stroke=\"#dc2626\" stroke-width=\"2\" opacity=\"0.8\">\n                    <line x1=\"154\" y1=\"4\" x2=\"171\" y2=\"21\"/>\n                    <line x1=\"171\" y1=\"4\" x2=\"154\" y2=\"21\"/>\n                </g>\n                <g stroke=\"#dc2626\" stroke-width=\"2\" opacity=\"0.8\">\n                    <line x1=\"154\" y1=\"29\" x2=\"171\" y2=\"46\"/>\n                    <line x1=\"171\" y1=\"29\" x2=\"154\" y2=\"46\"/>\n                </g>\n                <g stroke=\"#dc2626\" stroke-width=\"2\" opacity=\"0.8\">\n                    <line x1=\"179\" y1=\"29\" x2=\"196\" y2=\"46\"/>\n                    <line x1=\"196\" y1=\"29\" x2=\"179\" y2=\"46\"/>\n                </g>\n                <text x=\"187.5\" y=\"187.5\" font-size=\"18\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♕</text>\n                <text x=\"137.5\" y=\"37.5\" font-size=\"18\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♔</text>\n                <text x=\"187.5\" y=\"12.5\" font-size=\"18\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\">♚</text>\n                <circle cx=\"176\" cy=\"3\" r=\"5.5\" fill=\"#7f1d1d\"/>\n                <text x=\"176\" y=\"3\" font-size=\"6.5\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" font-weight=\"bold\">✕</text>\n                <text x=\"137.5\" y=\"209\" font-size=\"6.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">f7</text>\n                <text x=\"162.5\" y=\"209\" font-size=\"6.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">g8</text>\n                <text x=\"187.5\" y=\"209\" font-size=\"6.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">h8</text>\n                <text x=\"100\" y=\"218\" font-size=\"8\" fill=\"#7f1d1d\" text-anchor=\"middle\" font-weight=\"bold\">✕ SKAKMAT — Permainan Selesai!</text>\n            </svg>\n            <div style=\"display:flex; gap:8px; margin-top:4px; justify-content:center; flex-wrap:wrap;\">\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#ef4444;border-radius:2px;display:inline-block;opacity:0.8\"></span> Raja diserang\n                </span>\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#dc2626;border-radius:2px;display:inline-block;opacity:0.4\"></span> Semua jalan tertutup\n                </span>\n            </div>\n        </div>\n\n        <div class=\"text-content\">\n            <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">💀 Skakmat (Checkmate)</h3>\n            <p class=\"text-gray-600 leading-relaxed text-sm\">\n                Skakmat merupakan eskalasi tertinggi dari kondisi skak — yaitu ketika raja berada dalam ancaman langsung dan tidak tersedia satu pun langkah yang dapat menyelamatkannya. Tidak ada kotak aman untuk berpindah, tidak ada bidak己方 yang dapat memblok jalur serangan, dan penyerang tidak dapat ditangkap oleh bidak mana pun. Ketika ketiga syarat penyelamatan semuanya tertutup, permainan berakhir seketika. Itulah skakmat: sebuah kondisi final yang tidak memerlukan giliran tambahan untuk dikonfirmasi.\n                <br><br>\n                Diagram di samping menggambarkan salah satu pola skakmat yang paling sering dijumpai dalam permainan, yakni <em>back-rank mate</em>. Raja hitam (♚) terpojok di sudut <strong>h8</strong>, sementara ratu putih (♕) di <strong>h1</strong> memberikan tekanan vertikal yang langsung menyusuri kolom h. Di saat yang sama, raja putih (♔) yang berdiri di <strong>f7</strong> menguasai seluruh kotak pelarian yang tersisa — g8 dan g7 — sehingga raja hitam benar-benar terkurung tanpa celah.\n                <br><br>\n                Yang membedakan skakmat dari sekadar skak adalah ketiadaan absolut dari opsi penyelamatan. Dalam posisi ini, setiap kotak yang secara teoritis dapat dituju raja hitam sudah berada di bawah kendali bidak putih, ditandai dengan tanda silang pada diagram. Pemahaman tentang skakmat bukan hanya soal mengenali kapan permainan berakhir, tetapi juga soal membangun kemampuan untuk melihat jauh ke depan — merencanakan koordinasi bidak-bidak己方 agar secara kolektif mampu menutup seluruh ruang gerak raja lawan secara bersamaan.\n            </p>\n        </div>\n    </div>"},{"sub":true,"html":"<div class=\"content-row\" style=\"margin-top: 2rem; padding-top: 1.5rem; border-top: 2px dashed #e5e7eb;\">\n        <div class=\"board-panel relative\" style=\"float: right; margin-left: 1.5rem; margin-bottom: 1rem;\">\n            <svg viewBox=\"0 0 200 230\" class=\"w-full h-full\">\n                <rect width=\"200\" height=\"200\" fill=\"#769656\"/>\n                <g fill=\"#eeeed2\">\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"0\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"25\"/>\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"50\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"75\"/>\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"100\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"125\"/>\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"150\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"175\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"175\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"175\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"175\"/>\n                </g>\n                <rect x=\"0\" y=\"0\" width=\"25\" height=\"25\" fill=\"#f59e0b\" fill-opacity=\"0.5\"/>\n                <rect x=\"0\" y=\"25\" width=\"25\" height=\"25\" fill=\"#94a3b8\" fill-opacity=\"0.4\"/>\n                <rect x=\"25\" y=\"0\" width=\"25\" height=\"25\" fill=\"#94a3b8\" fill-opacity=\"0.4\"/>\n                <rect x=\"25\" y=\"25\" width=\"25\" height=\"25\" fill=\"#94a3b8\" fill-opacity=\"0.4\"/>\n                <g stroke=\"#64748b\" stroke-width=\"1.8\" opacity=\"0.8\">\n                    <line x1=\"4\" y1=\"29\" x2=\"21\" y2=\"46\"/>\n                    <line x1=\"21\" y1=\"29\" x2=\"4\" y2=\"46\"/>\n                </g>\n                <g stroke=\"#64748b\" stroke-width=\"1.8\" opacity=\"0.8\">\n                    <line x1=\"29\" y1=\"4\" x2=\"46\" y2=\"21\"/>\n                    <line x1=\"46\" y1=\"4\" x2=\"29\" y2=\"21\"/>\n                </g>\n                <g stroke=\"#64748b\" stroke-width=\"1.8\" opacity=\"0.8\">\n                    <line x1=\"29\" y1=\"29\" x2=\"46\" y2=\"46\"/>\n                    <line x1=\"46\" y1=\"29\" x2=\"29\" y2=\"46\"/>\n                </g>\n                <text x=\"62.5\" y=\"37.5\" font-size=\"18\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♕</text>\n                <text x=\"37.5\" y=\"62.5\" font-size=\"18\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♔</text>\n                <text x=\"12.5\" y=\"12.5\" font-size=\"18\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\">♚</text>\n                <rect x=\"0\" y=\"0\" width=\"11\" height=\"8\" rx=\"2\" fill=\"#f59e0b\"/>\n                <text x=\"5.5\" y=\"4\" font-size=\"4\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" font-weight=\"bold\">OK</text>\n                <rect x=\"55\" y=\"88\" width=\"90\" height=\"22\" rx=\"4\" fill=\"#f8fafc\" stroke=\"#64748b\" stroke-width=\"1\" fill-opacity=\"0.95\"/>\n                <text x=\"100\" y=\"97\" font-size=\"7\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">TIDAK ADA LANGKAH LEGAL</text>\n                <text x=\"100\" y=\"106\" font-size=\"6\" fill=\"#64748b\" text-anchor=\"middle\">Raja aman, tetapi tidak bisa bergerak</text>\n                <text x=\"12.5\" y=\"209\" font-size=\"6.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">a8</text>\n                <text x=\"37.5\" y=\"209\" font-size=\"6.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">b6</text>\n                <text x=\"62.5\" y=\"209\" font-size=\"6.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">c7</text>\n                <text x=\"100\" y=\"220\" font-size=\"8\" fill=\"#d97706\" text-anchor=\"middle\" font-weight=\"bold\">= STALEMATE — Hasil Seri / Remis!</text>\n            </svg>\n            <div style=\"display:flex; gap:6px; margin-top:4px; justify-content:center; flex-wrap:wrap;\">\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#f59e0b;border-radius:2px;display:inline-block;opacity:0.7\"></span> Raja (tidak diserang)\n                </span>\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#94a3b8;border-radius:2px;display:inline-block;opacity:0.7\"></span> Kotak terblokir\n                </span>\n            </div>\n        </div>\n\n        <div class=\"text-content\">\n            <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">🤝 Stalemate (Remis Paksa)</h3>\n            <p class=\"text-gray-600 leading-relaxed text-sm\">\n                Stalemate adalah kondisi yang secara permukaan tampak menyerupai skakmat, namun sesungguhnya memiliki perbedaan yang mendasar dan berdampak pada hasil akhir permainan secara dramatis. Kondisi ini terjadi ketika pemain yang sedang mendapat giliran tidak memiliki langkah legal satu pun, sementara rajanya tidak berada dalam ancaman skak. Karena raja tidak sedang diserang, kondisi ini tidak memenuhi syarat sebagai kekalahan — namun karena pemain tidak dapat bergerak ke mana pun, permainan tidak dapat dilanjutkan. Hasilnya adalah seri, atau dalam istilah catur disebut remis.\n                <br><br>\n                Diagram di samping mengilustrasikan situasi stalemate yang kerap menjadi jebakan berbahaya bagi pemain yang tidak berpengalaman. Raja hitam (♚) berdiri di <strong>a8</strong> dengan posisi yang secara teknis tidak sedang diserang — ditandai warna kuning dan lencana \"OK\" pada diagram. Namun seluruh kotak yang secara geometris dapat dijangkaunya, yakni <strong>a7</strong>, <strong>b7</strong>, dan <strong>b8</strong>, telah dikuasai oleh ratu putih (♕) di c7 dan raja putih (♔) di b6. Tidak ada satu pun kotak aman yang tersedia, dan tidak ada bidak hitam lain yang dapat bergerak. Giliran hitam, tetapi hitam tidak bisa berbuat apa-apa.\n                <br><br>\n                Inilah yang menjadikan stalemate sebagai salah satu konsep paling kritis untuk dipahami, terutama di fase akhir permainan. Pemain yang unggul materi secara signifikan pun dapat kehilangan kemenangan yang seharusnya diraih, hanya karena satu langkah yang tanpa sadar menutup seluruh ruang gerak lawan tanpa memberi skak terlebih dahulu. Oleh sebab itu, ketika mendekati kemenangan, kesadaran untuk selalu menyisakan setidaknya satu kotak gerak bagi raja lawan menjadi bagian dari disiplin teknis yang tidak boleh diabaikan.\n            </p>\n        </div>\n    </div>"},{"sub":true,"html":"<div style=\"margin-top: 2rem; padding-top: 1.5rem; border-top: 2px dashed #e5e7eb;\">\n        <h3 class=\"text-lg font-extrabold text-chess-green uppercase mb-3 leading-tight\">📊 Tabel Perbandingan: Skak, Skakmat, dan Stalemate</h3>\n        <p class=\"text-gray-600 text-sm mb-4 leading-relaxed\">Sebagai ringkasan, tabel berikut menyajikan perbedaan mendasar antara ketiga kondisi tersebut berdasarkan dua variabel utama: apakah raja sedang diserang, dan apakah masih terdapat langkah legal yang dapat dilakukan. Pemahaman terhadap dua variabel ini sudah cukup untuk membedakan ketiganya secara akurat dalam situasi permainan yang nyata.</p>\n        <div style=\"overflow-x:auto;\">\n            <table style=\"width:100%;border-collapse:collapse;font-size:13px;\">\n                <thead>\n                    <tr style=\"background:#f1f5f9;\">\n                        <th style=\"padding:8px 12px;text-align:left;border:1px solid #e2e8f0;color:#374151;\">Kondisi</th>\n                        <th style=\"padding:8px 12px;text-align:center;border:1px solid #e2e8f0;color:#374151;\">Raja Diserang?</th>\n                        <th style=\"padding:8px 12px;text-align:center;border:1px solid #e2e8f0;color:#374151;\">Ada Langkah Legal?</th>\n                        <th style=\"padding:8px 12px;text-align:center;border:1px solid #e2e8f0;color:#374151;\">Hasil</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <tr>\n                        <td style=\"padding:8px 12px;border:1px solid #e2e8f0;font-weight:bold;\">⚠️ Skak</td>\n                        <td style=\"padding:8px 12px;border:1px solid #e2e8f0;text-align:center;color:#ef4444;\">✔ Ya</td>\n                        <td style=\"padding:8px 12px;border:1px solid #e2e8f0;text-align:center;color:#22c55e;\">✔ Ya</td>\n                        <td style=\"padding:8px 12px;border:1px solid #e2e8f0;text-align:center;\">Permainan Berlanjut</td>\n                    </tr>\n                    <tr style=\"background:#fef2f2;\">\n                        <td style=\"padding:8px 12px;border:1px solid #e2e8f0;font-weight:bold;\">💀 Skakmat</td>\n                        <td style=\"padding:8px 12px;border:1px solid #e2e8f0;text-align:center;color:#ef4444;\">✔ Ya</td>\n                        <td style=\"padding:8px 12px;border:1px solid #e2e8f0;text-align:center;color:#ef4444;\">✘ Tidak</td>\n                        <td style=\"padding:8px 12px;border:1px solid #e2e8f0;text-align:center;font-weight:bold;color:#ef4444;\">Kalah — Permainan Selesai</td>\n                    </tr>\n                    <tr style=\"background:#fefce8;\">\n                        <td style=\"padding:8px 12px;border:1px solid #e2e8f0;font-weight:bold;\">🤝 Stalemate</td>\n                        <td style=\"padding:8px 12px;border:1px solid #e2e8f0;text-align:center;color:#22c55e;\">✘ Tidak</td>\n                        <td style=\"padding:8px 12px;border:1px solid #e2e8f0;text-align:center;color:#ef4444;\">✘ Tidak</td>\n                        <td style=\"padding:8px 12px;border:1px solid #e2e8f0;text-align:center;font-weight:bold;color:#d97706;\">Seri — Remis</td>\n                    </tr>\n                </tbody>\n            </table>\n        </div>\n    </div>"}]},{"id":"panduan-9","bab":"bab-dasar","nomor":"9","judul":"3 Prinsip Pembukaan Catur untuk Pemula: Kontrol Tengah, Development, dan Rokade","deskripsi":"Menguasai prinsip pembukaan catur adalah langkah pertama menuju permainan yang lebih kuat. Pelajari tiga prinsip dasar pembukaan yaitu kontrol tengah, pengembangan bidak, dan keamanan raja melalui rokade yang wajib dikuasai setiap pemula.","baris":[{"sub":false,"html":"<div class=\"content-row\">\n        <div class=\"text-content\">\n            <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">Tiga Prinsip Pembukaan Catur yang Wajib Dikuasai Pemula</h3>\n            <p class=\"text-gray-600 leading-relaxed text-sm\">\n                Pembukaan adalah fase paling awal dalam permainan catur, namun pengaruhnya terhadap jalannya posisi sangat jauh melampaui beberapa langkah pertama itu sendiri. Kesalahan yang dilakukan di fase ini jarang mengakibatkan kekalahan secara langsung, tetapi hampir selalu meninggalkan warisan berupa posisi yang lebih sempit, bidak yang pasif, atau raja yang rentan — masalah-masalah yang akan semakin terasa berat ketika memasuki fase tengah permainan. Bagi pemula, tujuan utama pembukaan bukan menghafal deretan variasi panjang yang ada di buku teori, melainkan membangun fondasi posisi yang sehat, aktif, dan aman sejak dini. Tiga prinsip dasar berikut sudah cukup untuk mencapai tujuan itu secara konsisten.\n            </p>\n        </div>\n    </div>"},{"sub":true,"html":"<div class=\"content-row\" style=\"margin-top: 2rem; padding-top: 1.5rem; border-top: 2px dashed #e5e7eb;\">\n        <div class=\"board-panel relative\" style=\"float: right; margin-left: 1.5rem; margin-bottom: 1rem;\">\n            <svg viewBox=\"0 0 200 220\" class=\"w-full h-full\">\n                <!-- Papan -->\n                <rect width=\"200\" height=\"200\" fill=\"#769656\"/>\n                <g fill=\"#eeeed2\">\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"0\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"25\"/>\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"50\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"75\"/>\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"100\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"125\"/>\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"150\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"175\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"175\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"175\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"175\"/>\n                </g>\n\n                <!-- 4 kotak pusat: e4(x100,y100), d4(x75,y100), e5(x100,y75), d5(x75,y75) -->\n                <!-- Highlight pusat utama -->\n                <rect x=\"75\" y=\"75\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.55\"/>\n                <rect x=\"100\" y=\"75\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.55\"/>\n                <rect x=\"75\" y=\"100\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.55\"/>\n                <rect x=\"100\" y=\"100\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.55\"/>\n\n                <!-- Border tebal di sekitar 4 kotak pusat -->\n                <rect x=\"75\" y=\"75\" width=\"50\" height=\"50\" fill=\"none\" stroke=\"#ca8a04\" stroke-width=\"2\" stroke-dasharray=\"4,2\"/>\n\n                <!-- Highlight extended center (pengaruh pusat) -->\n                <rect x=\"50\" y=\"50\" width=\"100\" height=\"100\" fill=\"#facc15\" fill-opacity=\"0.07\"/>\n\n                <!-- Pion putih sudah di e4 -->\n                <text x=\"112.5\" y=\"112.5\" font-size=\"18\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♙</text>\n                <!-- Pion hitam sudah di e5 -->\n                <text x=\"112.5\" y=\"87.5\" font-size=\"18\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\">♟</text>\n                <!-- Pion putih di d4 -->\n                <text x=\"87.5\" y=\"112.5\" font-size=\"18\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♙</text>\n\n                <!-- Label kotak pusat -->\n                <text x=\"87.5\" y=\"88\" font-size=\"5.5\" fill=\"#92400e\" text-anchor=\"middle\" font-weight=\"bold\">d5</text>\n                <text x=\"112.5\" y=\"103\" font-size=\"5.5\" fill=\"#92400e\" text-anchor=\"middle\" font-weight=\"bold\">e4</text>\n                <text x=\"87.5\" y=\"103\" font-size=\"5.5\" fill=\"#92400e\" text-anchor=\"middle\" font-weight=\"bold\">d4</text>\n                <text x=\"112.5\" y=\"88\" font-size=\"5.5\" fill=\"#92400e\" text-anchor=\"middle\" font-weight=\"bold\">e5</text>\n\n                <!-- Panah kontrol dari pion putih e4 ke berbagai arah -->\n                <defs>\n                    <marker id=\"arrow-center\" markerWidth=\"5\" markerHeight=\"5\" refX=\"4\" refY=\"2.5\" orient=\"auto\">\n                        <path d=\"M0,0 L5,2.5 L0,5 Z\" fill=\"#ca8a04\" opacity=\"0.7\"/>\n                    </marker>\n                </defs>\n\n                <!-- Label koordinat baris/kolom -->\n                <text x=\"62.5\" y=\"209\" font-size=\"6.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">c</text>\n                <text x=\"87.5\" y=\"209\" font-size=\"6.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">d</text>\n                <text x=\"112.5\" y=\"209\" font-size=\"6.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">e</text>\n                <text x=\"137.5\" y=\"209\" font-size=\"6.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">f</text>\n\n                <!-- Label judul -->\n                <text x=\"100\" y=\"219\" font-size=\"8\" fill=\"#ca8a04\" text-anchor=\"middle\" font-weight=\"bold\">★ KONTROL PUSAT — d4, d5, e4, e5</text>\n            </svg>\n            <div style=\"display:flex; gap:8px; margin-top:4px; justify-content:center; flex-wrap:wrap;\">\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#facc15;border-radius:2px;display:inline-block;opacity:0.8\"></span> 4 kotak pusat utama\n                </span>\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#facc15;border-radius:2px;display:inline-block;opacity:0.2\"></span> Area pengaruh\n                </span>\n            </div>\n        </div>\n\n        <div class=\"text-content\">\n            <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">① Kontrol Pusat Papan</h3>\n            <p class=\"text-gray-600 leading-relaxed text-sm\">\n                Prinsip pertama yang mendasari hampir seluruh teori pembukaan modern adalah penguasaan atas empat petak pusat papan, yakni <strong>d4</strong>, <strong>d5</strong>, <strong>e4</strong>, dan <strong>e5</strong>. Keempat petak ini bukan sekadar posisi geometris yang berada di tengah papan — melainkan titik-titik kendali yang menentukan seberapa bebas sebuah bidak dapat bergerak dan menjangkau bagian mana pun dari papan. Bidak yang ditempatkan atau yang menguasai petak-petak ini secara efektif memiliki jangkauan dan mobilitas yang jauh lebih besar dibandingkan bidak yang terdesak ke tepi.\n                <br><br>\n                Logika di balik prinsip ini cukup intuitif: dari pusat, bidak dapat dengan cepat berpindah ke sayap mana pun sesuai kebutuhan posisi. Sebuah kuda yang berdiri di e4, misalnya, mengancam delapan petak sekaligus dan dapat dialihkan ke sayap raja maupun ratu dalam hitungan dua langkah. Sebaliknya, kuda yang terpinggirkan di tepi papan kehilangan sebagian besar efektivitasnya. Hal yang sama berlaku untuk pion: pion yang menduduki pusat membatasi ruang gerak lawan dan membuka diagonal bagi gajah serta kolom bagi benteng.\n                <br><br>\n                Dalam praktiknya, langkah pembukaan yang paling umum dan paling sehat bagi pemula adalah membuka dengan pion ke <strong>e4</strong> atau <strong>d4</strong>, karena kedua langkah tersebut langsung merebut ruang pusat dan sekaligus membuka jalur pengembangan bagi gajah dan ratu. Memulai permainan dengan langkah pion sayap seperti a4 atau h4, di sisi lain, tidak memberikan pengaruh apa pun terhadap pusat dan hanya membuang tempo yang sangat berharga di fase pembukaan.\n            </p>\n        </div>\n    </div>"},{"sub":true,"html":"<div class=\"content-row\" style=\"margin-top: 2rem; padding-top: 1.5rem; border-top: 2px dashed #e5e7eb;\">\n        <div class=\"board-panel relative\" style=\"float: left; margin-right: 1.5rem; margin-bottom: 1rem;\">\n            <svg viewBox=\"0 0 200 220\" class=\"w-full h-full\">\n                <!-- Papan -->\n                <rect width=\"200\" height=\"200\" fill=\"#769656\"/>\n                <g fill=\"#eeeed2\">\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"0\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"25\"/>\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"50\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"75\"/>\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"100\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"125\"/>\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"150\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"175\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"175\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"175\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"175\"/>\n                </g>\n\n                <defs>\n                    <marker id=\"arrow-dev\" markerWidth=\"5\" markerHeight=\"5\" refX=\"4\" refY=\"2.5\" orient=\"auto\">\n                        <path d=\"M0,0 L5,2.5 L0,5 Z\" fill=\"#3b82f6\"/>\n                    </marker>\n                    <marker id=\"arrow-dev2\" markerWidth=\"5\" markerHeight=\"5\" refX=\"4\" refY=\"2.5\" orient=\"auto\">\n                        <path d=\"M0,0 L5,2.5 L0,5 Z\" fill=\"#8b5cf6\"/>\n                    </marker>\n                </defs>\n\n                <!-- Posisi setelah beberapa langkah development putih -->\n                <!-- Pion putih e4 -->\n                <text x=\"112.5\" y=\"112.5\" font-size=\"18\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♙</text>\n                <!-- Pion hitam e5 -->\n                <text x=\"112.5\" y=\"87.5\" font-size=\"18\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\">♟</text>\n\n                <!-- Kuda putih sudah ke f3 (sudah dikembangkan) -->\n                <rect x=\"125\" y=\"125\" width=\"25\" height=\"25\" fill=\"#3b82f6\" fill-opacity=\"0.3\"/>\n                <text x=\"137.5\" y=\"137.5\" font-size=\"18\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♘</text>\n\n                <!-- Kuda putih di g1 (belum dikembangkan, transparan) -->\n                <text x=\"162.5\" y=\"187.5\" font-size=\"18\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.2\">♘</text>\n\n                <!-- Panah kuda dari g1 ke f3 -->\n                <line x1=\"158\" y1=\"180\" x2=\"142\" y2=\"145\" stroke=\"#3b82f6\" stroke-width=\"1.5\" stroke-dasharray=\"3,2\" marker-end=\"url(#arrow-dev)\"/>\n\n                <!-- Gajah putih sudah ke c4 (sudah dikembangkan) -->\n                <rect x=\"50\" y=\"100\" width=\"25\" height=\"25\" fill=\"#8b5cf6\" fill-opacity=\"0.3\"/>\n                <text x=\"62.5\" y=\"112.5\" font-size=\"18\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♗</text>\n\n                <!-- Gajah putih di f1 (belum dikembangkan, transparan) -->\n                <text x=\"137.5\" y=\"187.5\" font-size=\"18\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.2\">♗</text>\n\n                <!-- Panah gajah dari f1 ke c4 (diagonal) -->\n                <line x1=\"132\" y1=\"180\" x2=\"72\" y2=\"118\" stroke=\"#8b5cf6\" stroke-width=\"1.5\" stroke-dasharray=\"3,2\" marker-end=\"url(#arrow-dev2)\"/>\n\n                <!-- Bidak yang belum berkembang (baris pertama putih, pasif) -->\n                <!-- Ratu, Raja, Benteng kiri, kuda kiri, gajah kiri — masih di tempat -->\n                <text x=\"12.5\" y=\"187.5\" font-size=\"14\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.35\">♖</text>\n                <text x=\"37.5\" y=\"187.5\" font-size=\"14\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.35\">♘</text>\n                <text x=\"87.5\" y=\"187.5\" font-size=\"14\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.35\">♕</text>\n                <text x=\"112.5\" y=\"187.5\" font-size=\"14\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.35\">♔</text>\n                <text x=\"187.5\" y=\"187.5\" font-size=\"14\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.35\">♖</text>\n\n                <!-- Label urutan development -->\n                <rect x=\"128\" y=\"128\" width=\"10\" height=\"10\" rx=\"5\" fill=\"#3b82f6\"/>\n                <text x=\"133\" y=\"133\" font-size=\"6\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" font-weight=\"bold\">1</text>\n                <rect x=\"53\" y=\"103\" width=\"10\" height=\"10\" rx=\"5\" fill=\"#8b5cf6\"/>\n                <text x=\"58\" y=\"108\" font-size=\"6\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" font-weight=\"bold\">2</text>\n\n                <!-- Label koordinat -->\n                <text x=\"62.5\" y=\"209\" font-size=\"6.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">c4</text>\n                <text x=\"137.5\" y=\"209\" font-size=\"6.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">f3</text>\n\n                <!-- Judul -->\n                <text x=\"100\" y=\"219\" font-size=\"8\" fill=\"#3b82f6\" text-anchor=\"middle\" font-weight=\"bold\">♘ DEVELOPMENT — Kuda & Gajah Aktif</text>\n            </svg>\n            <div style=\"display:flex; gap:8px; margin-top:4px; justify-content:center; flex-wrap:wrap;\">\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#3b82f6;border-radius:2px;display:inline-block;opacity:0.7\"></span> Kuda dikembangkan\n                </span>\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#8b5cf6;border-radius:2px;display:inline-block;opacity:0.7\"></span> Gajah dikembangkan\n                </span>\n            </div>\n        </div>\n\n        <div class=\"text-content\">\n            <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">② Pengembangan Bidak (Development)</h3>\n            <p class=\"text-gray-600 leading-relaxed text-sm\">\n                Prinsip kedua berkaitan dengan kecepatan dan kualitas pengembangan bidak, atau dalam terminologi catur disebut <em>development</em>. Development merujuk pada proses memindahkan bidak-bidak minor — terutama kuda dan gajah — dari baris pertama ke posisi aktif yang memberi mereka pengaruh nyata terhadap papan. Bidak yang masih berada di petak awalnya tidak memberikan kontribusi apa pun terhadap permainan, sementara waktu yang berlalu tanpa pengembangan memberi lawan keunggulan dalam hal koordinasi dan kesiapan menyerang.\n                <br><br>\n                Pada diagram di samping, terlihat dua bidak minor putih yang telah dikembangkan: kuda ke <strong>f3</strong> dan gajah ke <strong>c4</strong>. Kedua bidak ini sudah berada di posisi aktif — kuda di f3 mengontrol pusat dan mempersulit langkah lawan, sementara gajah di c4 mengarah ke diagonal yang kuat menuju pusat permainan. Bidak-bidak yang masih tertinggal di baris pertama tampak memudar, mencerminkan ketidakaktifan mereka.\n                <br><br>\n                Kesalahan yang paling sering dilakukan pemula dalam konteks development adalah menggerakkan bidak yang sama beberapa kali berturut-turut tanpa alasan posisional yang jelas, atau terlalu cepat mengeluarkan ratu sebelum bidak-bidak minor siap. Ratu yang keluar terlalu awal justru rentan dikejar oleh bidak-bidak lawan yang sedang berkembang, sehingga waktu yang dihabiskan untuk menyelamatkan ratu itu sendiri menjadi kerugian tempo yang serius. Prinsip sederhana yang berlaku adalah: setiap langkah di pembukaan idealnya memindahkan bidak baru ke posisi yang lebih aktif, bukan mengulang langkah yang sudah dilakukan.\n            </p>\n        </div>\n    </div>"},{"sub":true,"html":"<div class=\"content-row\" style=\"margin-top: 2rem; padding-top: 1.5rem; border-top: 2px dashed #e5e7eb;\">\n        <div class=\"board-panel relative\" style=\"float: right; margin-left: 1.5rem; margin-bottom: 1rem;\">\n            <svg viewBox=\"0 0 200 230\" class=\"w-full h-full\">\n                <!-- Papan -->\n                <rect width=\"200\" height=\"200\" fill=\"#769656\"/>\n                <g fill=\"#eeeed2\">\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"0\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"25\"/>\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"50\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"75\"/>\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"100\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"125\"/>\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"150\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"175\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"175\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"175\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"175\"/>\n                </g>\n\n                <defs>\n                    <marker id=\"arrow-castle-king\" markerWidth=\"5\" markerHeight=\"5\" refX=\"4\" refY=\"2.5\" orient=\"auto\">\n                        <path d=\"M0,0 L5,2.5 L0,5 Z\" fill=\"#16a34a\"/>\n                    </marker>\n                    <marker id=\"arrow-castle-rook\" markerWidth=\"5\" markerHeight=\"5\" refX=\"4\" refY=\"2.5\" orient=\"auto\">\n                        <path d=\"M0,0 L5,2.5 L0,5 Z\" fill=\"#0284c7\"/>\n                    </marker>\n                </defs>\n\n                <!-- Posisi SEBELUM rokade (transparan) -->\n                <!-- Raja putih di e1 (x100, y175) — posisi asal -->\n                <text x=\"112.5\" y=\"187.5\" font-size=\"18\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.25\">♔</text>\n                <!-- Benteng putih di h1 (x175, y175) — posisi asal -->\n                <text x=\"187.5\" y=\"187.5\" font-size=\"18\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.25\">♖</text>\n\n                <!-- Jalur rokade pendek: raja e1 → g1, benteng h1 → f1 -->\n                <!-- Highlight jalur yang harus bersih -->\n                <rect x=\"125\" y=\"175\" width=\"25\" height=\"25\" fill=\"#16a34a\" fill-opacity=\"0.2\"/>\n                <rect x=\"150\" y=\"175\" width=\"25\" height=\"25\" fill=\"#16a34a\" fill-opacity=\"0.2\"/>\n\n                <!-- Panah raja bergerak ke g1 (x150, y175) -->\n                <line x1=\"115\" y1=\"184\" x2=\"148\" y2=\"184\" stroke=\"#16a34a\" stroke-width=\"2\" marker-end=\"url(#arrow-castle-king)\"/>\n\n                <!-- Panah benteng bergerak ke f1 (x125, y175) -->\n                <line x1=\"182\" y1=\"190\" x2=\"152\" y2=\"190\" stroke=\"#0284c7\" stroke-width=\"2\" marker-end=\"url(#arrow-castle-rook)\"/>\n\n                <!-- Posisi SETELAH rokade (solid) -->\n                <!-- Raja putih sudah di g1 -->\n                <rect x=\"150\" y=\"175\" width=\"25\" height=\"25\" fill=\"#16a34a\" fill-opacity=\"0.3\"/>\n                <text x=\"162.5\" y=\"187.5\" font-size=\"18\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♔</text>\n\n                <!-- Benteng putih sudah di f1 -->\n                <rect x=\"125\" y=\"175\" width=\"25\" height=\"25\" fill=\"#0284c7\" fill-opacity=\"0.3\"/>\n                <text x=\"137.5\" y=\"187.5\" font-size=\"18\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♖</text>\n\n                <!-- Pion penjaga raja (f2, g2, h2) — benteng pertahanan -->\n                <text x=\"137.5\" y=\"162.5\" font-size=\"16\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♙</text>\n                <text x=\"162.5\" y=\"162.5\" font-size=\"16\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♙</text>\n                <text x=\"187.5\" y=\"162.5\" font-size=\"16\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♙</text>\n\n                <!-- Perisai/tameng di raja (aman) -->\n                <text x=\"162.5\" y=\"173\" font-size=\"7\" fill=\"#16a34a\" text-anchor=\"middle\" font-weight=\"bold\">★ AMAN</text>\n\n                <!-- Garis pembatas: raja sudah aman di belakang pion -->\n                <rect x=\"125\" y=\"150\" width=\"75\" height=\"3\" fill=\"#16a34a\" fill-opacity=\"0.4\" rx=\"1\"/>\n\n                <!-- Bidak hitam di atas (konteks) -->\n                <text x=\"112.5\" y=\"87.5\" font-size=\"16\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\">♟</text>\n                <text x=\"87.5\" y=\"87.5\" font-size=\"16\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\">♟</text>\n\n                <!-- Label -->\n                <text x=\"112.5\" y=\"209\" font-size=\"6.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">e1→g1</text>\n                <text x=\"162.5\" y=\"209\" font-size=\"6.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">Raja (g1)</text>\n                <text x=\"137.5\" y=\"209\" font-size=\"6.5\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">♖ (f1)</text>\n\n                <!-- Judul -->\n                <text x=\"100\" y=\"222\" font-size=\"7.5\" fill=\"#16a34a\" text-anchor=\"middle\" font-weight=\"bold\">♔ ROKADE PENDEK — Raja Terlindungi</text>\n            </svg>\n            <div style=\"display:flex; gap:8px; margin-top:4px; justify-content:center; flex-wrap:wrap;\">\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#16a34a;border-radius:2px;display:inline-block;opacity:0.7\"></span> Pergerakan Raja\n                </span>\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#0284c7;border-radius:2px;display:inline-block;opacity:0.7\"></span> Pergerakan Benteng\n                </span>\n            </div>\n        </div>\n\n        <div class=\"text-content\">\n            <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">③ Keamanan Raja — Rokade</h3>\n            <p class=\"text-gray-600 leading-relaxed text-sm\">\n                Prinsip ketiga, dan yang paling sering diabaikan oleh pemula, adalah mengamankan raja sesegera mungkin melalui rokade. Raja yang dibiarkan bertahan di pusat papan dalam waktu lama menjadi target yang sangat rentan, karena jalur-jalur di tengah papan cepat terbuka seiring berkembangnya permainan. Serangan terhadap raja yang belum rokade tidak membutuhkan rencana yang rumit — seringkali cukup membuka satu kolom atau diagonal di pusat untuk menciptakan ancaman yang langsung mengancam keselamatan raja.\n                <br><br>\n                Rokade adalah satu-satunya langkah dalam catur yang memperbolehkan dua bidak bergerak sekaligus dalam satu giliran. Dalam rokade pendek yang digambarkan pada diagram, raja berpindah dua kotak ke arah <strong>g1</strong>, sementara benteng secara otomatis melompat ke <strong>f1</strong> — posisi tepat di sebelah raja yang baru. Dengan langkah tunggal ini, dua tujuan besar tercapai: raja tersembunyi di belakang tembok pion yang kokoh di f2, g2, dan h2, sementara benteng teraktivasi ke kolom tengah yang lebih berpengaruh.\n                <br><br>\n                Bagi pemula, rokade pendek hampir selalu menjadi pilihan yang paling disarankan. Strukturnya lebih cepat dipersiapkan, hanya membutuhkan pengembangan kuda f3 dan gajah agar jalur di antara raja dan benteng sayap raja bersih. Rokade panjang memerlukan lebih banyak persiapan dan umumnya menghasilkan posisi yang lebih tajam dan kompleks — pilihan yang lebih cocok ketika pemain sudah memiliki pemahaman posisional yang lebih matang. Namun apapun jenis rokadinya yang dipilih, prinsipnya tetap sama: raja yang aman adalah raja yang dapat bertahan cukup lama untuk memenangkan permainan.\n            </p>\n        </div>\n    </div>"},{"sub":true,"html":"<div style=\"margin-top: 2rem; padding-top: 1.5rem; border-top: 2px dashed #e5e7eb;\">\n        <h3 class=\"text-lg font-extrabold text-chess-green uppercase mb-3 leading-tight\">📌 Kesimpulan: Tiga Prinsip, Satu Tujuan</h3>\n        <p class=\"text-gray-600 leading-relaxed text-sm\">\n            Ketiga prinsip pembukaan yang telah diuraikan — kontrol pusat, pengembangan bidak, dan keamanan raja melalui rokade — sesungguhnya bukan tiga hal yang terpisah, melainkan tiga dimensi dari satu tujuan yang sama: membangun posisi yang aktif, terkoordinasi, dan stabil sejak awal permainan. Kontrol pusat memberi bidak ruang dan mobilitas. Development memastikan semua bidak ikut berkontribusi sejak dini. Dan rokade menjamin bahwa raja tidak menjadi celah yang dieksploitasi lawan sebelum permainan sesungguhnya dimulai.\n            <br><br>\n            Yang perlu ditekankan adalah bahwa pemula tidak membutuhkan hafalan teori pembukaan yang mendalam untuk bisa memulai dengan baik. Dengan menerapkan ketiga prinsip ini secara konsisten dalam setiap partai, posisi pembukaan yang diperoleh akan jauh lebih sehat dan kompetitif dibandingkan posisi yang dibangun tanpa arah. Pemahaman terhadap prinsip jauh lebih berharga daripada hafalan variasi — karena prinsip dapat diterapkan dalam situasi apa pun, sementara hafalan hanya berlaku selama lawan mengikuti jalur yang diharapkan.\n        </p>\n    </div>"}]},{"id":"panduan-10","bab":"bab-dasar","nomor":"10","judul":"Pola Skakmat Dasar dalam Catur: Fool's Mate, Scholar's Mate, dan Back Rank Mate","deskripsi":"Mengenal pola skakmat dasar adalah kunci untuk menyerang dan bertahan dengan lebih baik. Pelajari fool's mate, scholar's mate, back rank mate, dan pola skakmat endgame yang wajib dikuasai setiap pemula catur.","baris":[{"sub":false,"html":"<div class=\"content-row\">\n        <div class=\"text-content\">\n            <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">Pola Skakmat Dasar dalam Catur yang Wajib Diketahui Pemula</h3>\n            <p class=\"text-gray-600 leading-relaxed text-sm\">\n                Mengenali pola skakmat dasar adalah salah satu cara paling efisien untuk meningkatkan kekuatan bermain secara signifikan dalam waktu singkat. Berbeda dengan hafalan variasi pembukaan yang panjang atau teori endgame yang kompleks, pola-pola skakmat ini bersifat langsung dan dapat segera diterapkan dalam permainan praktis. Lebih dari sekadar teknik serangan, memahami pola-pola ini juga membangun kepekaan defensif — pemain yang tahu bagaimana sebuah skakmat terjadi akan jauh lebih sulit dijatuhkan oleh ancaman yang sama. Dalam bagian ini, empat pola skakmat dasar akan diuraikan secara bertahap, dari yang paling sederhana hingga yang paling sering muncul dalam permainan nyata.\n            </p>\n        </div>\n    </div>"},{"sub":true,"html":"<div class=\"content-row\" style=\"margin-top: 2rem; padding-top: 1.5rem; border-top: 2px dashed #e5e7eb;\">\n        <div class=\"board-panel relative\" style=\"float: right; margin-left: 1.5rem; margin-bottom: 1rem;\">\n            <svg viewBox=\"0 0 200 225\" class=\"w-full h-full\">\n                <rect width=\"200\" height=\"200\" fill=\"#769656\"/>\n                <g fill=\"#eeeed2\">\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"0\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"25\"/>\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"50\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"75\"/>\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"100\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"125\"/>\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"150\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"175\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"175\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"175\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"175\"/>\n                </g>\n\n                <defs>\n                    <marker id=\"arrow-fools\" markerWidth=\"5\" markerHeight=\"5\" refX=\"4\" refY=\"2.5\" orient=\"auto\">\n                        <path d=\"M0,0 L5,2.5 L0,5 Z\" fill=\"#ef4444\"/>\n                    </marker>\n                    <marker id=\"arrow-fools-diag\" markerWidth=\"5\" markerHeight=\"5\" refX=\"4\" refY=\"2.5\" orient=\"auto\">\n                        <path d=\"M0,0 L5,2.5 L0,5 Z\" fill=\"#dc2626\"/>\n                    </marker>\n                </defs>\n\n                <!-- Posisi setelah 1.f3 e5 2.g4 -->\n                <!-- Pion putih f3 (x125, y125) — melemahkan diagonal -->\n                <rect x=\"125\" y=\"125\" width=\"25\" height=\"25\" fill=\"#ef4444\" fill-opacity=\"0.3\"/>\n                <text x=\"137.5\" y=\"137.5\" font-size=\"16\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♙</text>\n\n                <!-- Pion putih g4 (x150, y100) — melemahkan diagonal -->\n                <rect x=\"150\" y=\"100\" width=\"25\" height=\"25\" fill=\"#ef4444\" fill-opacity=\"0.3\"/>\n                <text x=\"162.5\" y=\"112.5\" font-size=\"16\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♙</text>\n\n                <!-- Pion hitam e5 (x100, y75) -->\n                <text x=\"112.5\" y=\"87.5\" font-size=\"16\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\">♟</text>\n\n                <!-- Raja putih di e1 (x100, y175) terkena skakmat -->\n                <rect x=\"100\" y=\"175\" width=\"25\" height=\"25\" fill=\"#ef4444\" fill-opacity=\"0.55\"/>\n                <text x=\"112.5\" y=\"187.5\" font-size=\"18\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♔</text>\n\n                <!-- Ratu hitam di h4 (x175, y100) — memberi skakmat -->\n                <rect x=\"175\" y=\"100\" width=\"25\" height=\"25\" fill=\"#1e293b\" fill-opacity=\"0.5\"/>\n                <text x=\"187.5\" y=\"112.5\" font-size=\"18\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\">♛</text>\n\n                <!-- Diagonal serangan ratu dari h4 ke e1 -->\n                <line x1=\"183\" y1=\"118\" x2=\"122\" y2=\"179\" stroke=\"#dc2626\" stroke-width=\"1.8\" stroke-dasharray=\"3,2\" marker-end=\"url(#arrow-fools-diag)\"/>\n\n                <!-- Highlight diagonal yang terbuka karena f3 dan g4 -->\n                <rect x=\"125\" y=\"125\" width=\"25\" height=\"25\" fill=\"#ef4444\" fill-opacity=\"0.15\"/>\n                <rect x=\"150\" y=\"100\" width=\"25\" height=\"25\" fill=\"#ef4444\" fill-opacity=\"0.15\"/>\n                <rect x=\"175\" y=\"100\" width=\"25\" height=\"25\" fill=\"#ef4444\" fill-opacity=\"0.05\"/>\n\n                <!-- Tanda # di raja putih -->\n                <circle cx=\"101\" cy=\"176\" r=\"5\" fill=\"#7f1d1d\"/>\n                <text x=\"101\" y=\"176\" font-size=\"5.5\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" font-weight=\"bold\">#</text>\n\n                <!-- Bidak hitam awal (konteks) -->\n                <text x=\"12.5\" y=\"12.5\" font-size=\"14\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.5\">♜</text>\n                <text x=\"37.5\" y=\"12.5\" font-size=\"14\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.5\">♞</text>\n                <text x=\"62.5\" y=\"12.5\" font-size=\"14\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.5\">♝</text>\n                <text x=\"87.5\" y=\"12.5\" font-size=\"14\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.5\">♚</text>\n                <text x=\"112.5\" y=\"12.5\" font-size=\"14\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.5\">♝</text>\n                <text x=\"137.5\" y=\"12.5\" font-size=\"14\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.5\">♞</text>\n                <text x=\"162.5\" y=\"12.5\" font-size=\"14\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.5\">♜</text>\n\n                <!-- Notasi -->\n                <text x=\"100\" y=\"210\" font-size=\"6.5\" fill=\"#374151\" text-anchor=\"middle\">1.f3 e5  2.g4  <tspan font-weight=\"bold\" fill=\"#ef4444\">...Qh4#</tspan></text>\n                <text x=\"100\" y=\"221\" font-size=\"8\" fill=\"#7f1d1d\" text-anchor=\"middle\" font-weight=\"bold\">✕ FOOL'S MATE — Skakmat 2 Langkah</text>\n            </svg>\n            <div style=\"display:flex; gap:8px; margin-top:4px; justify-content:center; flex-wrap:wrap;\">\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#ef4444;border-radius:2px;display:inline-block;opacity:0.6\"></span> Pion pelemah diagonal\n                </span>\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#1e293b;border-radius:2px;display:inline-block;opacity:0.6\"></span> Ratu penyerang (h4)\n                </span>\n            </div>\n        </div>\n\n        <div class=\"text-content\">\n            <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">① Fool's Mate</h3>\n            <p class=\"text-gray-600 leading-relaxed text-sm\">\n                Fool's Mate memegang rekor sebagai skakmat tercepat yang mungkin terjadi dalam permainan catur — selesai hanya dalam dua langkah. Meskipun sangat jarang muncul dalam permainan yang sesungguhnya karena membutuhkan kesalahan yang teramat mencolok dari pihak putih, pola ini memiliki nilai pedagogis yang tinggi karena ia mendemonstrasikan secara paling langsung apa yang terjadi ketika prinsip dasar pertahanan raja dilanggar.\n                <br><br>\n                Urutan langkahnya adalah sebagai berikut: putih membuka dengan <strong>1.f3</strong>, langkah yang sama sekali tidak membantu perkembangan dan justru melemahkan diagonal e1–h4. Hitam merespons dengan <strong>1...e5</strong>, menguasai pusat. Putih kemudian melanjutkan kesalahan dengan <strong>2.g4</strong>, membuka diagonal secara penuh. Hitam menutup partai dengan <strong>2...Qh4#</strong> — ratu hitam meluncur ke h4 dan memberi skakmat langsung. Raja putih tidak memiliki kotak pelarian, serangan tidak bisa diblok, dan ratu hitam tidak bisa ditangkap.\n                <br><br>\n                Apa yang membuat Fool's Mate begitu instruktif bukan kemunculannya, melainkan pesan yang dikandungnya: setiap langkah pion di depan raja membuka celah yang sebelumnya tertutup. Langkah f3 dan g4 secara bersamaan menghapus dua petak penjaga yang kritis di sekitar raja putih. Memahami mekanisme ini mengajarkan pemula untuk selalu mempertimbangkan dampak setiap langkah pion terhadap keamanan raja, jauh sebelum ancaman itu benar-benar terlihat di papan.\n            </p>\n        </div>\n    </div>"},{"sub":true,"html":"<div class=\"content-row\" style=\"margin-top: 2rem; padding-top: 1.5rem; border-top: 2px dashed #e5e7eb;\">\n        <div class=\"board-panel relative\" style=\"float: left; margin-right: 1.5rem; margin-bottom: 1rem;\">\n            <svg viewBox=\"0 0 200 225\" class=\"w-full h-full\">\n                <rect width=\"200\" height=\"200\" fill=\"#769656\"/>\n                <g fill=\"#eeeed2\">\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"0\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"25\"/>\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"50\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"75\"/>\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"100\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"100\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"125\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"125\"/>\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"150\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"150\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"175\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"175\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"175\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"175\"/>\n                </g>\n\n                <defs>\n                    <marker id=\"arrow-scholar1\" markerWidth=\"5\" markerHeight=\"5\" refX=\"4\" refY=\"2.5\" orient=\"auto\">\n                        <path d=\"M0,0 L5,2.5 L0,5 Z\" fill=\"#ef4444\"/>\n                    </marker>\n                    <marker id=\"arrow-scholar2\" markerWidth=\"5\" markerHeight=\"5\" refX=\"4\" refY=\"2.5\" orient=\"auto\">\n                        <path d=\"M0,0 L5,2.5 L0,5 Z\" fill=\"#f97316\"/>\n                    </marker>\n                </defs>\n\n                <!-- Posisi Scholar's Mate: 1.e4 e5 2.Bc4 Nc6 3.Qh5 Nf6?? 4.Qxf7# -->\n                <!-- Pion e4 putih -->\n                <text x=\"112.5\" y=\"112.5\" font-size=\"16\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♙</text>\n                <!-- Pion e5 hitam -->\n                <text x=\"112.5\" y=\"87.5\" font-size=\"16\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\">♟</text>\n\n                <!-- Gajah putih di c4 (x50, y100) — menyerang f7 -->\n                <rect x=\"50\" y=\"100\" width=\"25\" height=\"25\" fill=\"#f97316\" fill-opacity=\"0.3\"/>\n                <text x=\"62.5\" y=\"112.5\" font-size=\"18\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♗</text>\n\n                <!-- Ratu putih di h5 (x175, y75) — menyerang f7 -->\n                <rect x=\"175\" y=\"75\" width=\"25\" height=\"25\" fill=\"#ef4444\" fill-opacity=\"0.4\"/>\n                <text x=\"187.5\" y=\"87.5\" font-size=\"18\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♕</text>\n\n                <!-- Target: f7 (x125, y25) — titik terlemah hitam -->\n                <rect x=\"125\" y=\"25\" width=\"25\" height=\"25\" fill=\"#ef4444\" fill-opacity=\"0.6\"/>\n                <!-- Pion hitam f7 yang akan dimakan -->\n                <text x=\"137.5\" y=\"37.5\" font-size=\"16\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\">♟</text>\n\n                <!-- Raja hitam di e8 (x100, y0) terkena skakmat -->\n                <rect x=\"100\" y=\"0\" width=\"25\" height=\"25\" fill=\"#ef4444\" fill-opacity=\"0.5\"/>\n                <text x=\"112.5\" y=\"12.5\" font-size=\"18\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\">♚</text>\n\n                <!-- Tanda # di raja hitam -->\n                <circle cx=\"101\" cy=\"1\" r=\"5\" fill=\"#7f1d1d\"/>\n                <text x=\"101\" y=\"1\" font-size=\"5.5\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" font-weight=\"bold\">#</text>\n\n                <!-- Panah ratu ke f7 (serangan utama) -->\n                <line x1=\"180\" y1=\"82\" x2=\"145\" y2=\"38\" stroke=\"#ef4444\" stroke-width=\"2\" stroke-dasharray=\"3,2\" marker-end=\"url(#arrow-scholar1)\"/>\n\n                <!-- Panah gajah ke f7 (serangan pendukung) -->\n                <line x1=\"68\" y1=\"105\" x2=\"130\" y2=\"38\" stroke=\"#f97316\" stroke-width=\"1.5\" stroke-dasharray=\"3,2\" marker-end=\"url(#arrow-scholar2)\"/>\n\n                <!-- Label titik lemah -->\n                <text x=\"137.5\" y=\"33\" font-size=\"5\" fill=\"white\" text-anchor=\"middle\" font-weight=\"bold\">f7 !</text>\n\n                <!-- Kuda hitam Nc6 (x50, y50) -->\n                <text x=\"62.5\" y=\"62.5\" font-size=\"16\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\">♞</text>\n\n                <!-- Bidak hitam lainnya -->\n                <text x=\"12.5\" y=\"12.5\" font-size=\"14\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.4\">♜</text>\n                <text x=\"37.5\" y=\"12.5\" font-size=\"14\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.4\">♞</text>\n                <text x=\"62.5\" y=\"12.5\" font-size=\"14\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.4\">♝</text>\n                <text x=\"87.5\" y=\"12.5\" font-size=\"14\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.4\">♛</text>\n                <text x=\"162.5\" y=\"12.5\" font-size=\"14\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.4\">♝</text>\n                <text x=\"187.5\" y=\"12.5\" font-size=\"14\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.4\">♜</text>\n\n                <!-- Notasi -->\n                <text x=\"100\" y=\"210\" font-size=\"6\" fill=\"#374151\" text-anchor=\"middle\">1.e4 e5  2.Bc4  3.Qh5  <tspan font-weight=\"bold\" fill=\"#ef4444\">4.Qxf7#</tspan></text>\n                <text x=\"100\" y=\"221\" font-size=\"8\" fill=\"#7f1d1d\" text-anchor=\"middle\" font-weight=\"bold\">✕ SCHOLAR'S MATE — Skakmat 4 Langkah</text>\n            </svg>\n            <div style=\"display:flex; gap:8px; margin-top:4px; justify-content:center; flex-wrap:wrap;\">\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#ef4444;border-radius:2px;display:inline-block;opacity:0.7\"></span> Target f7 & Ratu\n                </span>\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#f97316;border-radius:2px;display:inline-block;opacity:0.7\"></span> Gajah pendukung\n                </span>\n            </div>\n        </div>\n\n        <div class=\"text-content\">\n            <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">② Scholar's Mate</h3>\n            <p class=\"text-gray-600 leading-relaxed text-sm\">\n                Scholar's Mate adalah pola skakmat empat langkah yang menjadi jebakan paling umum di level pemula. Keefektifannya terletak pada kesederhanaan ide dan kecepatan eksekusi: putih mengkonsentrasikan tekanan pada satu titik yang paling lemah dalam susunan awal hitam, yakni petak <strong>f7</strong>. Petak ini hanya dijaga oleh raja hitam sejak posisi awal, menjadikannya sasaran yang sangat rentan apabila hitam tidak memperhatikannya dengan seksama.\n                <br><br>\n                Seperti yang terlihat pada diagram, putih mengarahkan dua bidak secara bersamaan ke f7: gajah dari <strong>c4</strong> menyerang melalui diagonal, sementara ratu dari <strong>h5</strong> menambah tekanan dari arah yang berbeda. Ketika ratu akhirnya menangkap pion di f7 dengan <strong>4.Qxf7#</strong>, raja hitam di e8 tidak memiliki jalan keluar — kotak-kotak di sekitarnya dikuasai oleh kombinasi ratu dan gajah putih, sementara bidak-bidak hitam sendiri menghalangi peluang kabur.\n                <br><br>\n                Yang perlu dipahami bukan hanya urutan langkahnya, melainkan mengapa ancaman ini bekerja. Hitam kerap gagal mendeteksi Scholar's Mate karena terlalu fokus mengembangkan bidak己方 tanpa memeriksa ancaman langsung lawan. Cara pertahanan yang paling tepat adalah langkah seperti <strong>...Nf6</strong> — yang sekaligus mengusir ratu putih dari h5 dan mengembangkan kuda hitam — atau <strong>...g6</strong> yang menutup diagonal serangan ratu. Pertahanan yang baik terhadap Scholar's Mate mengajarkan prinsip yang lebih dalam: pengembangan bidak harus selalu berjalan seiring dengan kewaspadaan terhadap ancaman konkret lawan.\n            </p>\n        </div>\n    </div>"},{"sub":true,"html":"<div class=\"content-row\" style=\"margin-top: 2rem; padding-top: 1.5rem; border-top: 2px dashed #e5e7eb;\">\n        <div class=\"board-panel relative\" style=\"float: right; margin-left: 1.5rem; margin-bottom: 1rem;\">\n            <svg viewBox=\"0 0 200 225\" class=\"w-full h-full\">\n                <rect width=\"200\" height=\"200\" fill=\"#769656\"/>\n                <g fill=\"#eeeed2\">\n                    <rect x=\"0\" y=\"0\" width=\"25\" height=\"25\"/><rect x=\"50\" y=\"0\" width=\"25\" height=\"25\"/><rect x=\"100\" y=\"0\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"0\" width=\"25\" height=\"25\"/>\n                    <rect x=\"25\" y=\"25\" width=\"25\" height=\"25\"/><rect x=\"75\" y=\"25\" width=\"25\" height=\"25\"/><rect x=\"125\" y=\"25\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"25\" width=\"25\" height=\"25\"/>\n                    <rect x=\"0\" y=\"50\" width=\"25\" height=\"25\"/><rect x=\"50\" y=\"50\" width=\"25\" height=\"25\"/><rect x=\"100\" y=\"50\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"50\" width=\"25\" height=\"25\"/>\n                    <rect x=\"25\" y=\"75\" width=\"25\" height=\"25\"/><rect x=\"75\" y=\"75\" width=\"25\" height=\"25\"/><rect x=\"125\" y=\"75\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"75\" width=\"25\" height=\"25\"/>\n                    <rect x=\"0\" y=\"100\" width=\"25\" height=\"25\"/><rect x=\"50\" y=\"100\" width=\"25\" height=\"25\"/><rect x=\"100\" y=\"100\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"100\" width=\"25\" height=\"25\"/>\n                    <rect x=\"25\" y=\"125\" width=\"25\" height=\"25\"/><rect x=\"75\" y=\"125\" width=\"25\" height=\"25\"/><rect x=\"125\" y=\"125\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"125\" width=\"25\" height=\"25\"/>\n                    <rect x=\"0\" y=\"150\" width=\"25\" height=\"25\"/><rect x=\"50\" y=\"150\" width=\"25\" height=\"25\"/><rect x=\"100\" y=\"150\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"150\" width=\"25\" height=\"25\"/>\n                    <rect x=\"25\" y=\"175\" width=\"25\" height=\"25\"/><rect x=\"75\" y=\"175\" width=\"25\" height=\"25\"/><rect x=\"125\" y=\"175\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"175\" width=\"25\" height=\"25\"/>\n                </g>\n\n                <defs>\n                    <marker id=\"arr-backrank\" markerWidth=\"5\" markerHeight=\"5\" refX=\"4\" refY=\"2.5\" orient=\"auto\">\n                        <path d=\"M0,0 L5,2.5 L0,5 Z\" fill=\"#ef4444\"/>\n                    </marker>\n                    <marker id=\"arr-move\" markerWidth=\"5\" markerHeight=\"5\" refX=\"4\" refY=\"2.5\" orient=\"auto\">\n                        <path d=\"M0,0 L5,2.5 L0,5 Z\" fill=\"#0284c7\"/>\n                    </marker>\n                    <marker id=\"arr-luft\" markerWidth=\"5\" markerHeight=\"5\" refX=\"4\" refY=\"2.5\" orient=\"auto\">\n                        <path d=\"M0,0 L5,2.5 L0,5 Z\" fill=\"#22c55e\"/>\n                    </marker>\n                </defs>\n\n                <!-- Raja hitam di g8 (150, 0) terkena skakmat -->\n                <rect x=\"150\" y=\"0\" width=\"25\" height=\"25\" fill=\"#ef4444\" fill-opacity=\"0.55\"/>\n                <text x=\"162.5\" y=\"12.5\" font-size=\"18\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\">♚</text>\n                \n                <!-- Tanda # -->\n                <circle cx=\"151\" cy=\"1\" r=\"5\" fill=\"#7f1d1d\"/>\n                <text x=\"151\" y=\"1\" font-size=\"5.5\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" font-weight=\"bold\">#</text>\n\n                <!-- Pion f7(125,25), g7(150,25), h7(175,25) mengurung raja -->\n                <text x=\"137.5\" y=\"37.5\" font-size=\"16\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\">♟</text>\n                <text x=\"162.5\" y=\"37.5\" font-size=\"16\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\">♟</text>\n                <text x=\"187.5\" y=\"37.5\" font-size=\"16\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\">♟</text>\n\n                <!-- Kotak kabur f8, h8 diblok pion sendiri -->\n                <rect x=\"175\" y=\"0\" width=\"25\" height=\"25\" fill=\"#94a3b8\" fill-opacity=\"0.3\"/>\n                <g stroke=\"#64748b\" stroke-width=\"1.5\" opacity=\"0.6\">\n                    <line x1=\"179\" y1=\"4\" x2=\"196\" y2=\"21\"/><line x1=\"196\" y1=\"4\" x2=\"179\" y2=\"21\"/>\n                </g>\n                <rect x=\"125\" y=\"0\" width=\"25\" height=\"25\" fill=\"#94a3b8\" fill-opacity=\"0.3\"/>\n                <g stroke=\"#64748b\" stroke-width=\"1.5\" opacity=\"0.6\">\n                    <line x1=\"129\" y1=\"4\" x2=\"146\" y2=\"21\"/><line x1=\"146\" y1=\"4\" x2=\"129\" y2=\"21\"/>\n                </g>\n\n                <!-- Benteng putih mendarat di e8 (100, 0) melalui kolom e yang terbuka -->\n                <rect x=\"100\" y=\"0\" width=\"25\" height=\"25\" fill=\"#0284c7\" fill-opacity=\"0.3\"/>\n                <text x=\"112.5\" y=\"12.5\" font-size=\"18\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♖</text>\n\n                <!-- Panah 1: Benteng naik dari e1 ke e8 (kolom e terbuka) -->\n                <line x1=\"112.5\" y1=\"170\" x2=\"112.5\" y2=\"25\" stroke=\"#0284c7\" stroke-width=\"1.8\" stroke-dasharray=\"2,2\" opacity=\"0.6\" marker-end=\"url(#arr-move)\"/>\n                \n                <!-- Panah 2: Benteng e8 menyetrum g8 secara horizontal -->\n                <line x1=\"125\" y1=\"12.5\" x2=\"142\" y2=\"12.5\" stroke=\"#ef4444\" stroke-width=\"2\" marker-end=\"url(#arr-backrank)\"/>\n\n                <!-- Solusi luft: panah ke h6 -->\n                <rect x=\"175\" y=\"50\" width=\"25\" height=\"25\" fill=\"#22c55e\" fill-opacity=\"0.35\"/>\n                <text x=\"187.5\" y=\"62.5\" font-size=\"9\" fill=\"#15803d\" text-anchor=\"middle\" dominant-baseline=\"central\" font-weight=\"bold\">luft</text>\n                <line x1=\"187.5\" y1=\"37\" x2=\"187.5\" y2=\"52\" stroke=\"#22c55e\" stroke-width=\"1.5\" marker-end=\"url(#arr-luft)\"/>\n\n                <!-- Benteng bayangan di e1 (awal mula) -->\n                <text x=\"112.5\" y=\"187.5\" font-size=\"16\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.3\">♖</text>\n\n                <!-- Label -->\n                <text x=\"100\" y=\"210\" font-size=\"6.5\" fill=\"#374151\" text-anchor=\"middle\">Benteng masuk e8 → Skak horizontal ke g8</text>\n                <text x=\"100\" y=\"221\" font-size=\"8\" fill=\"#7f1d1d\" text-anchor=\"middle\" font-weight=\"bold\">✕ BACK RANK MATE — Terjebak Pion Sendiri</text>\n            </svg>\n            <div style=\"display:flex; gap:8px; margin-top:4px; justify-content:center; flex-wrap:wrap;\">\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#0284c7;border-radius:2px;display:inline-block;opacity:0.5\"></span> Jalur masuk (kolom e)\n                </span>\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#ef4444;border-radius:2px;display:inline-block;opacity:0.7\"></span> Skak horizontal\n                </span>\n            </div>\n        </div>\n        <div class=\"text-content\">\n            <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">③ Back Rank Mate</h3>\n            <p class=\"text-gray-600 leading-relaxed text-sm\">\n                Di antara semua pola skakmat dasar yang ada, Back Rank Mate adalah yang paling sering muncul dalam permainan praktis — bahkan di tingkat menengah sekalipun. Pola ini terjadi ketika raja yang telah melakukan rokade terjebak di baris belakang oleh barisan pionnya sendiri, dan tidak memiliki kotak pelarian ketika benteng atau ratu lawan berhasil menerobos masuk ke baris tersebut.\n                <br><br>\n                Diagram di samping menggambarkan mekanisme ini secara logis. Raja hitam berada di <strong>g8</strong>, berlindung di balik pion f7, g7, dan h7. Kolom g tertutup oleh pion, sehingga musuh tidak bisa menyerang dari depan. Namun, karena kolom <strong>e</strong> terbuka, benteng putih meluncur masuk dari <strong>e1</strong> ke <strong>e8</strong>. Dari petak e8, benteng tersebut memberikan skak secara horizontal menyusuri baris kedelapan langsung ke g8. Raja tidak bisa kabur karena terhalang pionnya sendiri.\n                <br><br>\n                Pencegahan terhadap Back Rank Mate cukup dengan menciptakan <em>luft</em> (lubang udara/pelarian) bagi raja. Langkah sederhana seperti <strong>...h6</strong> atau <strong>...g6</strong> pada saat yang tepat sudah cukup untuk memberikan raja kotak pelarian, sehingga skak di baris belakang tidak lagi berakibat fatal.\n            </p>\n        </div>\n    </div>"},{"sub":true,"html":"<div class=\"content-row\" style=\"margin-top: 2rem; padding-top: 1.5rem; border-top: 2px dashed #e5e7eb;\">\n        <div class=\"board-panel relative\" style=\"float: left; margin-right: 1.5rem; margin-bottom: 1rem;\">\n            <svg viewBox=\"0 0 200 250\" class=\"w-full h-full\">\n                <defs>\n                    <marker id=\"arrow-eg1\" markerWidth=\"5\" markerHeight=\"5\" refX=\"4\" refY=\"2.5\" orient=\"auto\">\n                        <path d=\"M0,0 L5,2.5 L0,5 Z\" fill=\"#8b5cf6\"/>\n                    </marker>\n                    <marker id=\"arrow-eg2\" markerWidth=\"5\" markerHeight=\"5\" refX=\"4\" refY=\"2.5\" orient=\"auto\">\n                        <path d=\"M0,0 L5,2.5 L0,5 Z\" fill=\"#0284c7\"/>\n                    </marker>\n                </defs>\n\n                <!-- ===== PANEL ATAS: Raja + Ratu vs Raja ===== -->\n                <rect width=\"200\" height=\"95\" fill=\"#769656\"/>\n                <g fill=\"#eeeed2\">\n                    <!-- 4 baris atas saja (papan mini) -->\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"0\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"0\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"25\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"25\"/>\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"50\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"50\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"75\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"75\"/>\n                </g>\n\n                <!-- Raja hitam terpojok di a8 (x0,y0) -->\n                <rect x=\"0\" y=\"0\" width=\"25\" height=\"25\" fill=\"#ef4444\" fill-opacity=\"0.5\"/>\n                <text x=\"12.5\" y=\"12.5\" font-size=\"18\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\">♚</text>\n                <circle cx=\"1\" cy=\"1\" r=\"5\" fill=\"#7f1d1d\"/>\n                <text x=\"1\" y=\"1\" font-size=\"5.5\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" font-weight=\"bold\">#</text>\n\n                <!-- Ratu putih di b6 (x25,y50) memberi skakmat -->\n                <rect x=\"25\" y=\"50\" width=\"25\" height=\"25\" fill=\"#8b5cf6\" fill-opacity=\"0.3\"/>\n                <text x=\"37.5\" y=\"62.5\" font-size=\"18\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♕</text>\n\n                <!-- Raja putih di c7 (x50,y25) mendukung -->\n                <rect x=\"50\" y=\"25\" width=\"25\" height=\"25\" fill=\"#8b5cf6\" fill-opacity=\"0.2\"/>\n                <text x=\"62.5\" y=\"37.5\" font-size=\"18\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♔</text>\n\n                <!-- Highlight area yang dikontrol ratu (memotong kotak kabur) -->\n                <rect x=\"0\" y=\"25\" width=\"25\" height=\"25\" fill=\"#8b5cf6\" fill-opacity=\"0.2\"/>\n                <rect x=\"25\" y=\"0\" width=\"25\" height=\"25\" fill=\"#8b5cf6\" fill-opacity=\"0.2\"/>\n                <g stroke=\"#6d28d9\" stroke-width=\"1.5\" opacity=\"0.6\">\n                    <line x1=\"29\" y1=\"4\" x2=\"21\" y2=\"21\"/>\n                </g>\n\n                <!-- Panah: ratu mengontrol a8 dari b6 -->\n                <line x1=\"36\" y1=\"58\" x2=\"14\" y2=\"17\" stroke=\"#8b5cf6\" stroke-width=\"1.5\" stroke-dasharray=\"2,2\" marker-end=\"url(#arrow-eg1)\"/>\n\n                <!-- Label panel atas -->\n                <text x=\"130\" y=\"15\" font-size=\"6.5\" fill=\"white\" text-anchor=\"middle\" font-weight=\"bold\">RAJA + RATU</text>\n                <text x=\"130\" y=\"25\" font-size=\"6\" fill=\"#e2e8f0\" text-anchor=\"middle\">vs Raja</text>\n                \n                <!-- Garis pemisah -->\n                <rect x=\"0\" y=\"95\" width=\"200\" height=\"3\" fill=\"#1e293b\" opacity=\"0.3\"/>\n\n                <!-- ===== PANEL BAWAH: Raja + Benteng vs Raja (Tangga) ===== -->\n                <rect y=\"98\" width=\"200\" height=\"100\" fill=\"#769656\"/>\n                <g fill=\"#eeeed2\">\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"98\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"98\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"98\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"98\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"123\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"123\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"123\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"123\"/>\n                    <rect width=\"25\" height=\"25\" x=\"0\" y=\"148\"/><rect width=\"25\" height=\"25\" x=\"50\" y=\"148\"/><rect width=\"25\" height=\"25\" x=\"100\" y=\"148\"/><rect width=\"25\" height=\"25\" x=\"150\" y=\"148\"/>\n                    <rect width=\"25\" height=\"25\" x=\"25\" y=\"173\"/><rect width=\"25\" height=\"25\" x=\"75\" y=\"173\"/><rect width=\"25\" height=\"25\" x=\"125\" y=\"173\"/><rect width=\"25\" height=\"25\" x=\"175\" y=\"173\"/>\n                </g>\n\n                <!-- Raja hitam terdorong ke tepi di a8 panel bawah (y=98) -->\n                <rect x=\"0\" y=\"98\" width=\"25\" height=\"25\" fill=\"#ef4444\" fill-opacity=\"0.5\"/>\n                <text x=\"12.5\" y=\"110.5\" font-size=\"18\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\">♚</text>\n                <circle cx=\"1\" cy=\"99\" r=\"5\" fill=\"#7f1d1d\"/>\n                <text x=\"1\" y=\"99\" font-size=\"5.5\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" font-weight=\"bold\">#</text>\n\n                <!-- Benteng putih di h8 (x175, y98) — memberi skakmat horizontal (metode tangga) -->\n                <rect x=\"175\" y=\"98\" width=\"25\" height=\"25\" fill=\"#0284c7\" fill-opacity=\"0.3\"/>\n                <text x=\"187.5\" y=\"110.5\" font-size=\"18\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♖</text>\n\n                <!-- Panah benteng ke a8 (skakmat) -->\n                <line x1=\"172\" y1=\"110.5\" x2=\"30\" y2=\"110.5\" stroke=\"#0284c7\" stroke-width=\"1.8\" stroke-dasharray=\"3,2\" marker-end=\"url(#arrow-eg2)\"/>\n\n                <!-- Highlight baris 8 (tangga terakhir) -->\n                <rect x=\"0\" y=\"98\" width=\"200\" height=\"25\" fill=\"#0284c7\" fill-opacity=\"0.07\"/>\n\n                <!-- Raja putih mendukung di b6 (x25, y148) -->\n                <rect x=\"25\" y=\"148\" width=\"25\" height=\"25\" fill=\"#0284c7\" fill-opacity=\"0.2\"/>\n                <text x=\"37.5\" y=\"160.5\" font-size=\"18\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♔</text>\n\n                <!-- Tangga: ilustrasi posisi sebelumnya (transparan) -->\n                <text x=\"187.5\" y=\"135.5\" font-size=\"16\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.2\">♖</text>\n                <line x1=\"187.5\" y1=\"132\" x2=\"187.5\" y2=\"116\" stroke=\"#0284c7\" stroke-width=\"1\" stroke-dasharray=\"2,2\" opacity=\"0.4\" marker-end=\"url(#arrow-eg2)\"/>\n\n                <!-- Label panel bawah -->\n                <text x=\"130\" y=\"115\" font-size=\"6.5\" fill=\"white\" text-anchor=\"middle\" font-weight=\"bold\">RAJA + BENTENG</text>\n                <text x=\"130\" y=\"125\" font-size=\"6\" fill=\"#e2e8f0\" text-anchor=\"middle\">vs Raja (Metode Tangga)</text>\n                <text x=\"120\" y=\"158\" font-size=\"22\" text-anchor=\"middle\" dominant-baseline=\"central\" fill=\"white\">♔</text>\n                <text x=\"148\" y=\"158\" font-size=\"8\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">+</text>\n                <text x=\"165\" y=\"158\" font-size=\"22\" text-anchor=\"middle\" dominant-baseline=\"central\" fill=\"white\">♖</text>\n\n                <!-- Label judul keseluruhan -->\n                <text x=\"100\" y=\"208\" font-size=\"7\" fill=\"#374151\" text-anchor=\"middle\">Atas: Ratu #  |  Bawah: Benteng # (Metode Tangga)</text>\n                <text x=\"100\" y=\"221\" font-size=\"8\" fill=\"#0284c7\" text-anchor=\"middle\" font-weight=\"bold\">♔ POLA SKAKMAT ENDGAME DASAR</text>\n                <text x=\"100\" y=\"233\" font-size=\"6.5\" fill=\"#64748b\" text-anchor=\"middle\">⚠ Hindari stalemate: sisakan 1 kotak legal bagi lawan</text>\n            </svg>\n            <div style=\"display:flex; gap:8px; margin-top:4px; justify-content:center; flex-wrap:wrap;\">\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#8b5cf6;border-radius:2px;display:inline-block;opacity:0.7\"></span> Raja + Ratu\n                </span>\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#0284c7;border-radius:2px;display:inline-block;opacity:0.7\"></span> Raja + Benteng (Tangga)\n                </span>\n            </div>\n        </div>\n\n        <div class=\"text-content\">\n            <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">④ Pola Skakmat Endgame Dasar</h3>\n            <p class=\"text-gray-600 leading-relaxed text-sm\">\n                Memasuki fase akhir permainan, dua pola skakmat yang paling fundamental untuk dikuasai adalah raja dan ratu melawan raja, serta raja dan benteng melawan raja. Kedua situasi ini muncul secara langsung dari konversi keunggulan material yang diperoleh sepanjang permainan, sehingga ketidakmampuan menyelesaikannya berarti membiarkan kemenangan yang sudah di tangan berpotensi meluap menjadi hasil seri.\n                <br><br>\n                <strong>Raja dan ratu melawan raja</strong> adalah teknik yang secara teori paling mudah dipahami, meskipun dalam praktiknya pemula kerap terburu-buru dan justru menghasilkan stalemate. Prinsip dasarnya bukan langsung mengejar skakmat, melainkan mempersempit wilayah gerak raja lawan secara bertahap dan sistematis. Ratu digunakan untuk memotong kolom atau baris, mengurangi jumlah kotak yang dapat dijangkau raja lawan sedikit demi sedikit, sementara raja己方 dibawa mendekat untuk memperkuat pengepungan. Setelah ruang raja lawan cukup sempit dan terdesak ke sudut atau tepi, skakmat dapat diberikan dengan aman seperti yang terlihat pada panel atas diagram — ratu di b6 memberi skakmat ke raja a8 dengan dukungan raja putih di c7.\n                <br><br>\n                <strong>Raja dan benteng melawan raja</strong> memerlukan teknik yang sedikit lebih spesifik, yang dikenal sebagai metode tangga. Benteng digunakan untuk memotong baris secara horizontal, memaksa raja lawan mundur satu baris demi satu baris, sementara raja己方 terus maju mendekati raja lawan untuk membantu menutup kotak-kotak yang tersisa. Proses ini dilakukan berulang seperti pola tangga — benteng memotong satu baris, raja maju, benteng memotong baris berikutnya — hingga raja lawan akhirnya terdorong ke tepi dan terkena skakmat seperti yang ditunjukkan pada panel bawah.\n                <br><br>\n                Dalam kedua teknik ini, ancaman terbesar justru datang dari diri sendiri: stalemate. Terlalu agresif dalam membatasi ruang gerak lawan, tanpa memastikan bahwa raja lawan masih memiliki setidaknya satu langkah legal, dapat mengakhiri permainan sebagai hasil seri alih-alih kemenangan. Kesadaran untuk selalu menjaga keseimbangan antara mempersempit ruang dan tidak menutupnya secara prematur adalah keterampilan teknis yang paling membedakan pemain yang benar-benar mampu mengkonversi keunggulan material menjadi kemenangan penuh.\n            </p>\n        </div>\n    </div>"},{"sub":true,"html":"<div style=\"margin-top: 2rem; padding-top: 1.5rem; border-top: 2px dashed #e5e7eb;\">\n        <h3 class=\"text-lg font-extrabold text-chess-green uppercase mb-3 leading-tight\">📌 Kesimpulan: Pola sebagai Bahasa Visual Catur</h3>\n        <p class=\"text-gray-600 leading-relaxed text-sm\">\n            Keempat pola skakmat yang telah diuraikan — Fool's Mate, Scholar's Mate, Back Rank Mate, dan pola-pola endgame dasar — sesungguhnya bukan sekadar teknik yang perlu dihafal, melainkan representasi visual dari prinsip-prinsip catur yang lebih dalam. Fool's Mate mengajarkan tentang keamanan diagonal raja. Scholar's Mate mengajarkan tentang kelemahan struktural petak f7 dan pentingnya mewaspadai ancaman konkret. Back Rank Mate mengajarkan bahwa struktur pertahanan yang tampak solid pun dapat berbalik menjadi jebakan. Dan pola-pola endgame mengajarkan bahwa keunggulan material baru bernilai ketika pemain mampu mengkonversinya menjadi skakmat secara teknis dan sabar.\n            <br><br>\n            Pemain yang terbiasa mengenali pola-pola ini akan memiliki keunggulan besar dalam kecepatan membaca posisi. Alih-alih menghitung langkah demi langkah dari awal setiap kali, mereka sudah mengenali bentuk akhir yang sedang menuju ke mana dan dapat merencanakan dengan jauh lebih efisien. Itulah mengapa studi pola skakmat, meski terlihat sederhana, merupakan investasi pemahaman yang dampaknya terasa jauh melampaui level pemula.\n        </p>\n    </div>"}]},{"id":"panduan-11","bab":"bab-dasar","nomor":"11","judul":"Taktik Dasar Catur: Fork, Pin, dan Skewer yang Wajib Dikuasai Pemula","deskripsi":"Taktik adalah kunci untuk memenangkan material dan menciptakan peluang menang dalam catur. Pelajari tiga taktik dasar yang paling sering terjadi yaitu fork, pin, dan skewer beserta cara mengenali dan menggunakannya dalam permainan.","baris":[{"sub":false,"html":"<div class=\"content-row\">\n        <div class=\"text-content\">\n            <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">Tiga Taktik Dasar Catur yang Paling Sering Digunakan</h3>\n            <p class=\"text-gray-600 leading-relaxed text-sm\">\n                Taktik dalam catur merujuk pada rangkaian langkah konkret yang bertujuan memperoleh keuntungan langsung, baik berupa material, posisi, maupun ancaman yang tidak dapat ditangkis. Berbeda dengan strategi yang bersifat jangka panjang dan abstrak, taktik bersifat presisi dan segera — hasilnya terlihat dalam hitungan langkah. Bagi pemula yang ingin meningkatkan kekuatan bermain secara cepat, penguasaan tiga pola taktis dasar sudah cukup untuk mengubah kualitas permainan secara signifikan. Ketiga pola tersebut adalah <em>fork</em>, <em>pin</em>, dan <em>skewer</em> — tiga motif yang muncul dengan frekuensi paling tinggi dalam permainan praktis di semua level.\n            </p>\n        </div>\n    </div>"},{"sub":true,"html":"<div class=\"content-row\" style=\"margin-top: 2rem; padding-top: 1.5rem; border-top: 2px dashed #e5e7eb;\">\n        <div class=\"board-panel relative\" style=\"float: right; margin-left: 1.5rem; margin-bottom: 1rem;\">\n            <svg viewBox=\"0 0 200 220\" class=\"w-full h-full\">\n                <rect width=\"200\" height=\"200\" fill=\"#769656\"/>\n                <g fill=\"#eeeed2\">\n                    <rect x=\"0\"   y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"100\" y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"150\" y=\"0\"   width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"125\" y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"175\" y=\"25\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"100\" y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"150\" y=\"50\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"125\" y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"175\" y=\"75\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"100\" width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"100\" width=\"25\" height=\"25\"/><rect x=\"100\" y=\"100\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"100\" width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"125\" width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"125\" width=\"25\" height=\"25\"/><rect x=\"125\" y=\"125\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"125\" width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"150\" width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"150\" width=\"25\" height=\"25\"/><rect x=\"100\" y=\"150\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"150\" width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"175\" width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"175\" width=\"25\" height=\"25\"/><rect x=\"125\" y=\"175\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"175\" width=\"25\" height=\"25\"/>\n                </g>\n\n                <defs>\n                    <marker id=\"arr-fork1\" markerWidth=\"5\" markerHeight=\"5\" refX=\"4\" refY=\"2.5\" orient=\"auto\">\n                        <path d=\"M0,0 L5,2.5 L0,5 Z\" fill=\"#ef4444\"/>\n                    </marker>\n                    <marker id=\"arr-fork2\" markerWidth=\"5\" markerHeight=\"5\" refX=\"4\" refY=\"2.5\" orient=\"auto\">\n                        <path d=\"M0,0 L5,2.5 L0,5 Z\" fill=\"#f97316\"/>\n                    </marker>\n                </defs>\n\n                <!--\n                    ROYAL FORK: Kuda putih di c7 menyerang Raja hitam e8 dan Ratu hitam a8\n                    Kolom: a=0, b=25, c=50, d=75, e=100, f=125, g=150, h=175\n                    Baris: 8=y0, 7=y25, 6=y50, 5=y75\n                    Center = (col+12.5, row+12.5)\n\n                    Kuda putih c7 → (62.5, 37.5)  [TIDAK DI KOTAK ASLI - ini FORK position]\n                    Wait - c7 = col=50, row=25 → center = (62.5, 37.5) ✓\n                    Hmm, tapi Kuda di c7 fork ke e8 dan a8 bukan langkah L yang benar.\n                    \n                    Kuda c7: bisa menyerang a8, a6, b5, d5, e6, e8 ✓\n                    Jadi fork: Kuda c7 → Raja e8 + Ratu a8 ✓✓\n                    \n                    Kuda putih c7  → col=50,  row=25 → center (62.5,  37.5)\n                    Raja hitam e8  → col=100, row=0  → center (112.5, 12.5)\n                    Ratu hitam a8  → col=0,   row=0  → center (12.5,  12.5)\n                -->\n\n                <!-- Highlight kuda putih c7 -->\n                <rect x=\"50\" y=\"25\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n\n                <!-- Highlight target 1: Raja hitam e8 -->\n                <rect x=\"100\" y=\"0\" width=\"25\" height=\"25\" fill=\"#ef4444\" fill-opacity=\"0.45\"/>\n                <!-- Highlight target 2: Ratu hitam a8 -->\n                <rect x=\"0\" y=\"0\" width=\"25\" height=\"25\" fill=\"#f97316\" fill-opacity=\"0.45\"/>\n\n                <!-- Panah fork 1: Kuda c7 → Raja e8 -->\n                <line x1=\"68\" y1=\"32\" x2=\"107\" y2=\"17\"\n                      stroke=\"#ef4444\" stroke-width=\"2\"\n                      stroke-dasharray=\"3,2\" marker-end=\"url(#arr-fork1)\"/>\n                <!-- Panah fork 2: Kuda c7 → Ratu a8 -->\n                <line x1=\"57\" y1=\"32\" x2=\"18\" y2=\"17\"\n                      stroke=\"#f97316\" stroke-width=\"2\"\n                      stroke-dasharray=\"3,2\" marker-end=\"url(#arr-fork2)\"/>\n\n                <!-- BIDAK -->\n                <!-- Kuda putih c7 → (62.5, 37.5) -->\n                <text x=\"62.5\" y=\"37.5\" font-size=\"19\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\">♘</text>\n                <!-- Raja hitam e8 → (112.5, 12.5) -->\n                <text x=\"112.5\" y=\"12.5\" font-size=\"19\" fill=\"black\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\">♚</text>\n                <!-- Ratu hitam a8 → (12.5, 12.5) -->\n                <text x=\"12.5\" y=\"12.5\" font-size=\"19\" fill=\"black\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\">♛</text>\n\n                <!-- Label \"skak!\" di raja -->\n                <circle cx=\"122\" cy=\"4\" r=\"5\" fill=\"#ef4444\"/>\n                <text x=\"122\" y=\"4\" font-size=\"5\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\" font-weight=\"bold\">!</text>\n\n                <!-- Label \"akan hilang\" di ratu -->\n                <rect x=\"0\" y=\"22\" width=\"25\" height=\"7\" rx=\"2\" fill=\"#f97316\" fill-opacity=\"0.8\"/>\n                <text x=\"12.5\" y=\"26.5\" font-size=\"4\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\" font-weight=\"bold\">HILANG</text>\n\n                <!-- Label kotak -->\n                <text x=\"62.5\"  y=\"209\" font-size=\"6\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">c7</text>\n                <text x=\"112.5\" y=\"209\" font-size=\"6\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">e8</text>\n                <text x=\"12.5\"  y=\"209\" font-size=\"6\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">a8</text>\n\n                <!-- Judul -->\n                <text x=\"100\" y=\"218\" font-size=\"8\" fill=\"#b45309\" text-anchor=\"middle\" font-weight=\"bold\">♘ FORK — Kuda Menyerang 2 Target</text>\n            </svg>\n            <div style=\"display:flex; gap:8px; margin-top:4px; justify-content:center; flex-wrap:wrap;\">\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#facc15;border-radius:2px;display:inline-block;opacity:0.7\"></span> Kuda (penyerang)\n                </span>\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#ef4444;border-radius:2px;display:inline-block;opacity:0.7\"></span> Target 1 (Raja)\n                </span>\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#f97316;border-radius:2px;display:inline-block;opacity:0.7\"></span> Target 2 (Ratu)\n                </span>\n            </div>\n        </div>\n\n        <div class=\"text-content\">\n            <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">① Fork (Serangan Ganda)</h3>\n            <p class=\"text-gray-600 leading-relaxed text-sm\">\n                Fork adalah taktik di mana satu bidak menyerang dua atau lebih target lawan secara bersamaan dalam satu langkah. Karena setiap pemain hanya memiliki satu giliran untuk merespons, lawan yang terkena fork hanya dapat menyelamatkan salah satu dari target yang terancam — target lainnya akan jatuh. Efektivitas fork terletak pada prinsip efisiensi yang sangat sederhana: satu langkah menciptakan dua masalah sekaligus, dan lawan tidak memiliki cukup waktu untuk menyelesaikan keduanya.\n                <br><br>\n                Meskipun fork secara teknis dapat dilakukan oleh bidak apa pun, kuda adalah pelaku fork yang paling efektif dan paling sering dijumpai. Pola pergerakan kuda yang berbentuk huruf L membuatnya mampu menyerang posisi yang tidak terlihat jelas oleh lawan, terutama pemain yang belum terbiasa menghitung jalur kuda secara visual. Diagram di samping menggambarkan bentuk fork yang paling merusak: <em>royal fork</em>. Kuda putih di <strong>c7</strong> menyerang raja hitam di <strong>e8</strong> dan ratu hitam di <strong>a8</strong> secara bersamaan. Karena raja wajib diselamatkan terlebih dahulu — ini bukan pilihan, melainkan aturan — ratu hitam yang bernilai sembilan poin dibiarkan tanpa pertahanan dan akan diambil pada langkah berikutnya.\n                <br><br>\n                Memahami fork bukan hanya soal mengenali polanya, tetapi juga soal membiasakan diri untuk selalu mencari kemungkinan serangan ganda sebelum menentukan langkah. Pemain yang terlatih secara taktis tidak hanya melihat satu ancaman dalam setiap posisi — mereka secara otomatis memeriksa apakah ada kotak tertentu yang memungkinkan satu bidak menjangkau dua target sekaligus. Kebiasaan ini, jika dikembangkan sejak awal, akan menjadi salah satu sumber kemenangan material yang paling konsisten sepanjang karier bermain.\n            </p>\n        </div>\n    </div>"},{"sub":true,"html":"<div class=\"content-row\" style=\"margin-top: 2rem; padding-top: 1.5rem; border-top: 2px dashed #e5e7eb;\">\n        <div class=\"board-panel relative\" style=\"float: left; margin-right: 1.5rem; margin-bottom: 1rem;\">\n            <svg viewBox=\"0 0 200 220\" class=\"w-full h-full\">\n                <rect width=\"200\" height=\"200\" fill=\"#769656\"/>\n                <g fill=\"#eeeed2\">\n                    <rect x=\"0\"   y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"100\" y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"150\" y=\"0\"   width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"125\" y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"175\" y=\"25\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"100\" y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"150\" y=\"50\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"125\" y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"175\" y=\"75\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"100\" width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"100\" width=\"25\" height=\"25\"/><rect x=\"100\" y=\"100\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"100\" width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"125\" width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"125\" width=\"25\" height=\"25\"/><rect x=\"125\" y=\"125\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"125\" width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"150\" width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"150\" width=\"25\" height=\"25\"/><rect x=\"100\" y=\"150\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"150\" width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"175\" width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"175\" width=\"25\" height=\"25\"/><rect x=\"125\" y=\"175\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"175\" width=\"25\" height=\"25\"/>\n                </g>\n\n                <defs>\n                    <marker id=\"arr-pin\" markerWidth=\"5\" markerHeight=\"5\" refX=\"4\" refY=\"2.5\" orient=\"auto\">\n                        <path d=\"M0,0 L5,2.5 L0,5 Z\" fill=\"#8b5cf6\"/>\n                    </marker>\n                </defs>\n\n                <!--\n                    PIN ABSOLUT: Gajah putih b5 → pin Kuda hitam d7 → Raja hitam e8\n                    Gajah putih b5 → col=25,  row=75  → center (37.5,  87.5)\n                    Kuda hitam  d7 → col=75,  row=25  → center (87.5,  37.5)\n                    Raja hitam  e8 → col=100, row=0   → center (112.5, 12.5)\n                -->\n\n                <!-- Jalur diagonal pin (b5 → d7 → e8) -->\n                <line x1=\"37.5\" y1=\"87.5\" x2=\"112.5\" y2=\"12.5\"\n                      stroke=\"#8b5cf6\" stroke-width=\"1.8\"\n                      stroke-dasharray=\"3,2\" opacity=\"0.6\"/>\n\n                <!-- Highlight zona pin -->\n                <!-- Gajah putih b5 (penyerang) -->\n                <rect x=\"25\" y=\"75\" width=\"25\" height=\"25\" fill=\"#8b5cf6\" fill-opacity=\"0.35\"/>\n                <!-- Kuda hitam d7 (yang di-pin) -->\n                <rect x=\"75\" y=\"25\" width=\"25\" height=\"25\" fill=\"#facc15\" fill-opacity=\"0.5\"/>\n                <!-- Raja hitam e8 (dilindungi) -->\n                <rect x=\"100\" y=\"0\" width=\"25\" height=\"25\" fill=\"#ef4444\" fill-opacity=\"0.35\"/>\n\n                <!-- Tanda gembok di kuda (terkunci) -->\n                <rect x=\"78\" y=\"15\" width=\"19\" height=\"10\" rx=\"2\" fill=\"#92400e\" fill-opacity=\"0.85\"/>\n                <text x=\"87.5\" y=\"21\" font-size=\"5\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\" font-weight=\"bold\">🔒 PIN</text>\n\n                <!-- BIDAK -->\n                <!-- Gajah putih b5 → (37.5, 87.5) -->\n                <text x=\"37.5\" y=\"87.5\" font-size=\"19\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\">♗</text>\n                <!-- Kuda hitam d7 → (87.5, 37.5) -->\n                <text x=\"87.5\" y=\"37.5\" font-size=\"19\" fill=\"black\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\">♞</text>\n                <!-- Raja hitam e8 → (112.5, 12.5) -->\n                <text x=\"112.5\" y=\"12.5\" font-size=\"19\" fill=\"black\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\">♚</text>\n\n                <!-- Panah: arah pin dari gajah ke menembus kuda sampai raja -->\n                <line x1=\"43\" y1=\"82\" x2=\"107\" y2=\"18\"\n                      stroke=\"#8b5cf6\" stroke-width=\"2\"\n                      marker-end=\"url(#arr-pin)\"/>\n\n                <!-- Label kotak -->\n                <text x=\"37.5\"  y=\"209\" font-size=\"6\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">b5</text>\n                <text x=\"87.5\"  y=\"209\" font-size=\"6\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">d7</text>\n                <text x=\"112.5\" y=\"209\" font-size=\"6\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">e8</text>\n\n                <!-- Label penjelasan di papan -->\n                <text x=\"37.5\" y=\"105\" font-size=\"5\" fill=\"white\" text-anchor=\"middle\" opacity=\"0.8\">penyerang</text>\n                <text x=\"87.5\" y=\"55\" font-size=\"5\" fill=\"#92400e\" text-anchor=\"middle\" font-weight=\"bold\">terkunci</text>\n                <text x=\"112.5\" y=\"5\" font-size=\"5\" fill=\"white\" text-anchor=\"middle\" font-weight=\"bold\" opacity=\"0.8\">♚ target</text>\n\n                <!-- Judul -->\n                <text x=\"100\" y=\"218\" font-size=\"8\" fill=\"#7c3aed\" text-anchor=\"middle\" font-weight=\"bold\">♗ PIN — Bidak Terkunci di Garis</text>\n            </svg>\n            <div style=\"display:flex; gap:8px; margin-top:4px; justify-content:center; flex-wrap:wrap;\">\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#8b5cf6;border-radius:2px;display:inline-block;opacity:0.7\"></span> Gajah (penyerang)\n                </span>\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#facc15;border-radius:2px;display:inline-block;opacity:0.7\"></span> Kuda (di-pin)\n                </span>\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#ef4444;border-radius:2px;display:inline-block;opacity:0.5\"></span> Raja (target)\n                </span>\n            </div>\n        </div>\n\n        <div class=\"text-content\">\n            <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">② Pin (Penguncian)</h3>\n            <p class=\"text-gray-600 leading-relaxed text-sm\">\n                Pin adalah kondisi taktis di mana sebuah bidak lawan secara efektif kehilangan kebebasan bergerak karena di belakangnya, pada garis yang sama, terdapat bidak yang bernilai lebih tinggi. Jika bidak depan dipindahkan, bidak di belakangnya — yang selama ini terlindungi oleh posisi bidak depan — akan langsung terekspos dan dapat diserang. Kekuatan utama pin bukan selalu soal mengambil bidak secara langsung, melainkan soal melumpuhkan fungsi sebuah bidak dan membuatnya menjadi beban dalam struktur pertahanan lawan.\n                <br><br>\n                Diagram di samping mengilustrasikan sebuah <em>pin absolut</em> yang merupakan bentuk paling kuat dari taktik ini. Gajah putih di <strong>b5</strong> menyerang kuda hitam di <strong>d7</strong> melalui diagonal. Di belakang kuda tersebut, tepat pada garis diagonal yang sama, berdiri raja hitam di <strong>e8</strong>. Karena memindahkan kuda berarti membuka serangan langsung ke raja — sebuah langkah yang secara hukum permainan tidak diperbolehkan — kuda tersebut benar-benar terkunci di tempatnya. Ia tidak dapat bergerak ke mana pun, menjadikannya bidak yang lumpuh dan tidak berguna selama pin berlangsung.\n                <br><br>\n                Selain pin absolut, terdapat pula <em>pin relatif</em> yang bekerja dengan prinsip serupa namun konsekuensi yang berbeda. Dalam pin relatif, bidak di belakang bukan raja melainkan bidak berharga lain seperti ratu. Bidak depan secara teknis masih boleh bergerak, tetapi melakukannya berarti mengorbankan ratu — sebuah pertukaran yang hampir tidak pernah menguntungkan. Baik pin absolut maupun relatif, keduanya paling sering dieksekusi oleh bidak-bidak yang bergerak dalam garis panjang: gajah melalui diagonal, dan benteng melalui baris atau kolom. Pemain yang terbiasa mencari peluang pin akan menemukan bahwa taktik ini muncul dengan frekuensi yang mengejutkan, terutama ketika bidak-bidak lawan tidak terkoordinasi dengan baik.\n            </p>\n        </div>\n    </div>"},{"sub":true,"html":"<div class=\"content-row\" style=\"margin-top: 2rem; padding-top: 1.5rem; border-top: 2px dashed #e5e7eb;\">\n        <div class=\"board-panel relative\" style=\"float: right; margin-left: 1.5rem; margin-bottom: 1rem;\">\n            <svg viewBox=\"0 0 200 220\" class=\"w-full h-full\">\n                <rect width=\"200\" height=\"200\" fill=\"#769656\"/>\n                <g fill=\"#eeeed2\">\n                    <rect x=\"0\"   y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"100\" y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"150\" y=\"0\"   width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"125\" y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"175\" y=\"25\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"100\" y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"150\" y=\"50\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"125\" y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"175\" y=\"75\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"100\" width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"100\" width=\"25\" height=\"25\"/><rect x=\"100\" y=\"100\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"100\" width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"125\" width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"125\" width=\"25\" height=\"25\"/><rect x=\"125\" y=\"125\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"125\" width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"150\" width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"150\" width=\"25\" height=\"25\"/><rect x=\"100\" y=\"150\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"150\" width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"175\" width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"175\" width=\"25\" height=\"25\"/><rect x=\"125\" y=\"175\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"175\" width=\"25\" height=\"25\"/>\n                </g>\n\n                <defs>\n                    <marker id=\"arr-skew\" markerWidth=\"5\" markerHeight=\"5\" refX=\"4\" refY=\"2.5\" orient=\"auto\">\n                        <path d=\"M0,0 L5,2.5 L0,5 Z\" fill=\"#0284c7\"/>\n                    </marker>\n                    <marker id=\"arr-flee\" markerWidth=\"5\" markerHeight=\"5\" refX=\"4\" refY=\"2.5\" orient=\"auto\">\n                        <path d=\"M0,0 L5,2.5 L0,5 Z\" fill=\"#ef4444\"/>\n                    </marker>\n                </defs>\n\n                <!--\n                    SKEWER: Benteng putih a1 → skewer Raja hitam a4 → Ratu hitam a8\n                    Benteng putih a1 → col=0, row=175 → center (12.5, 187.5)\n                    Raja hitam   a4 → col=0, row=100 → center (12.5, 112.5)\n                    Ratu hitam   a8 → col=0, row=0   → center (12.5, 12.5)\n                -->\n\n                <!-- Highlight kolom a (jalur skewer) -->\n                <rect x=\"0\" y=\"0\" width=\"25\" height=\"200\" fill=\"#0284c7\" fill-opacity=\"0.07\"/>\n\n                <!-- Highlight penyerang: Benteng putih a1 -->\n                <rect x=\"0\" y=\"175\" width=\"25\" height=\"25\" fill=\"#0284c7\" fill-opacity=\"0.35\"/>\n                <!-- Highlight target depan: Raja hitam a4 (dipaksa pindah) -->\n                <rect x=\"0\" y=\"100\" width=\"25\" height=\"25\" fill=\"#ef4444\" fill-opacity=\"0.45\"/>\n                <!-- Highlight target belakang: Ratu hitam a8 (akan jatuh) -->\n                <rect x=\"0\" y=\"0\" width=\"25\" height=\"25\" fill=\"#f97316\" fill-opacity=\"0.45\"/>\n\n                <!-- Panah skewer: Benteng a1 → menuju Raja a4 → menembus ke Ratu a8 -->\n                <line x1=\"12.5\" y1=\"172\" x2=\"12.5\" y2=\"118\"\n                      stroke=\"#0284c7\" stroke-width=\"2\"\n                      stroke-dasharray=\"3,2\" marker-end=\"url(#arr-skew)\"/>\n\n                <!-- Panah lanjutan menembus ke ratu (setelah raja kabur) -->\n                <line x1=\"12.5\" y1=\"97\" x2=\"12.5\" y2=\"20\"\n                      stroke=\"#0284c7\" stroke-width=\"1.5\"\n                      stroke-dasharray=\"2,2\" opacity=\"0.5\"\n                      marker-end=\"url(#arr-skew)\"/>\n\n                <!-- Panah raja kabur ke samping -->\n                <line x1=\"18\" y1=\"108\" x2=\"32\" y2=\"108\"\n                      stroke=\"#ef4444\" stroke-width=\"1.5\"\n                      marker-end=\"url(#arr-flee)\"/>\n\n                <!-- BIDAK -->\n                <!-- Benteng putih a1 → (12.5, 187.5) -->\n                <text x=\"12.5\" y=\"187.5\" font-size=\"19\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\">♖</text>\n                <!-- Raja hitam a4 → (12.5, 112.5) -->\n                <text x=\"12.5\" y=\"112.5\" font-size=\"19\" fill=\"black\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\">♚</text>\n                <!-- Ratu hitam a8 → (12.5, 12.5) -->\n                <text x=\"12.5\" y=\"12.5\" font-size=\"19\" fill=\"black\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\">♛</text>\n\n                <!-- Label \"skak!\" di raja -->\n                <circle cx=\"22\" cy=\"103\" r=\"5\" fill=\"#ef4444\"/>\n                <text x=\"22\" y=\"103\" font-size=\"5\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\" font-weight=\"bold\">!</text>\n\n                <!-- Label \"akan hilang\" di ratu -->\n                <rect x=\"0\" y=\"22\" width=\"25\" height=\"7\" rx=\"2\" fill=\"#f97316\" fill-opacity=\"0.8\"/>\n                <text x=\"12.5\" y=\"26.5\" font-size=\"4\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\" font-weight=\"bold\">HILANG</text>\n\n                <!-- Label \"kabur\" di raja -->\n                <text x=\"42\" y=\"105\" font-size=\"5\" fill=\"#ef4444\" font-weight=\"bold\">kabur</text>\n\n                <!-- Label kotak -->\n                <text x=\"12.5\" y=\"209\" font-size=\"6\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">a</text>\n\n                <!-- Label baris -->\n                <text x=\"195\" y=\"187.5\" font-size=\"5.5\" fill=\"white\" text-anchor=\"end\" dominant-baseline=\"central\" opacity=\"0.7\">1</text>\n                <text x=\"195\" y=\"112.5\" font-size=\"5.5\" fill=\"white\" text-anchor=\"end\" dominant-baseline=\"central\" opacity=\"0.7\">4</text>\n                <text x=\"195\" y=\"12.5\"  font-size=\"5.5\" fill=\"white\" text-anchor=\"end\" dominant-baseline=\"central\" opacity=\"0.7\">8</text>\n\n                <!-- Judul -->\n                <text x=\"100\" y=\"218\" font-size=\"8\" fill=\"#0369a1\" text-anchor=\"middle\" font-weight=\"bold\">♖ SKEWER — Target Berharga Dipaksa Pergi</text>\n            </svg>\n            <div style=\"display:flex; gap:8px; margin-top:4px; justify-content:center; flex-wrap:wrap;\">\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#0284c7;border-radius:2px;display:inline-block;opacity:0.7\"></span> Benteng (penyerang)\n                </span>\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#ef4444;border-radius:2px;display:inline-block;opacity:0.7\"></span> Raja (dipaksa kabur)\n                </span>\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#f97316;border-radius:2px;display:inline-block;opacity:0.7\"></span> Ratu (jatuh)\n                </span>\n            </div>\n        </div>\n\n        <div class=\"text-content\">\n            <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">③ Skewer (Tusukan)</h3>\n            <p class=\"text-gray-600 leading-relaxed text-sm\">\n                Skewer adalah kebalikan konseptual dari pin, dan memahami perbedaan di antara keduanya sangat penting untuk membangun penglihatan taktis yang tajam. Jika dalam pin bidak yang kurang berharga berada di depan dan melindungi bidak yang lebih berharga di belakang, dalam skewer urutannya dibalik: bidak yang lebih berharga justru berada di garis depan dan langsung terancam. Ketika bidak berharga tersebut dipaksa pergi untuk menyelamatkan diri, bidak di belakangnya — yang sebelumnya tersembunyi — menjadi terbuka dan langsung menjadi korban.\n                <br><br>\n                Diagram di samping menunjukkan sebuah skewer vertikal yang sangat khas. Benteng putih di <strong>a1</strong> menyerang raja hitam di <strong>a4</strong> melalui kolom a. Raja hitam berada dalam skak dan wajib pindah — misalnya ke b4 atau b3. Namun begitu raja berpindah, ratu hitam di <strong>a8</strong> yang selama ini berada di belakangnya pada kolom yang sama menjadi terbuka sepenuhnya. Benteng putih akan langsung mengambil ratu tersebut pada langkah berikutnya, menghasilkan keuntungan material yang besar.\n                <br><br>\n                Skewer paling sering terjadi pada garis-garis terbuka — baik kolom vertikal melalui benteng maupun diagonal panjang melalui gajah — terutama di fase tengah dan akhir permainan ketika papan mulai terbuka dan jalur-jalur panjang tidak lagi terhalang oleh pion. Salah satu bentuk skewer yang paling umum dan paling devastatif adalah skewer diagonal oleh gajah terhadap raja dan ratu yang kebetulan berada pada diagonal yang sama. Situasi seperti ini kerap muncul secara tiba-tiba, terutama setelah pertukaran bidak yang membuka diagonal, dan pemain yang tidak terbiasa memeriksa garis-garis panjang akan menjadi korbannya berulang kali tanpa memahami mengapa.\n            </p>\n        </div>\n    </div>"},{"sub":true,"html":"<div style=\"margin-top: 2rem; padding-top: 1.5rem; border-top: 2px dashed #e5e7eb;\">\n        <h3 class=\"text-lg font-extrabold text-chess-green uppercase mb-3 leading-tight\">📊 Perbandingan: Fork vs Pin vs Skewer</h3>\n        <p class=\"text-gray-600 text-sm mb-4 leading-relaxed\">\n            Untuk memperjelas hubungan dan perbedaan antara ketiga taktik dasar ini, tabel berikut merangkum mekanisme, pelaku utama, dan hasil khas dari masing-masing pola. Pemahaman terhadap perbedaan struktural ini membantu pemain mengenali peluang taktis dengan lebih cepat dan akurat dalam situasi permainan yang nyata.\n        </p>\n        <div style=\"overflow-x:auto;\">\n            <table style=\"width:100%;border-collapse:collapse;font-size:13px;\">\n                <thead>\n                    <tr style=\"background:#f1f5f9;\">\n                        <th style=\"padding:8px 12px;text-align:left;border:1px solid #e2e8f0;color:#374151;\">Taktik</th>\n                        <th style=\"padding:8px 12px;text-align:center;border:1px solid #e2e8f0;color:#374151;\">Mekanisme</th>\n                        <th style=\"padding:8px 12px;text-align:center;border:1px solid #e2e8f0;color:#374151;\">Pelaku Utama</th>\n                        <th style=\"padding:8px 12px;text-align:center;border:1px solid #e2e8f0;color:#374151;\">Hasil</th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <tr>\n                        <td style=\"padding:8px 12px;border:1px solid #e2e8f0;font-weight:bold;\">♘ Fork</td>\n                        <td style=\"padding:8px 12px;border:1px solid #e2e8f0;text-align:center;\">1 bidak menyerang 2+ target</td>\n                        <td style=\"padding:8px 12px;border:1px solid #e2e8f0;text-align:center;\">Kuda (paling sering)</td>\n                        <td style=\"padding:8px 12px;border:1px solid #e2e8f0;text-align:center;\">Menang salah satu target</td>\n                    </tr>\n                    <tr style=\"background:#faf5ff;\">\n                        <td style=\"padding:8px 12px;border:1px solid #e2e8f0;font-weight:bold;\">♗ Pin</td>\n                        <td style=\"padding:8px 12px;border:1px solid #e2e8f0;text-align:center;\">Bidak depan terkunci, melindungi target di belakang</td>\n                        <td style=\"padding:8px 12px;border:1px solid #e2e8f0;text-align:center;\">Gajah, Benteng</td>\n                        <td style=\"padding:8px 12px;border:1px solid #e2e8f0;text-align:center;\">Bidak depan lumpuh / jatuh</td>\n                    </tr>\n                    <tr style=\"background:#f0f9ff;\">\n                        <td style=\"padding:8px 12px;border:1px solid #e2e8f0;font-weight:bold;\">♖ Skewer</td>\n                        <td style=\"padding:8px 12px;border:1px solid #e2e8f0;text-align:center;\">Target berharga di depan dipaksa pergi, korban di belakang</td>\n                        <td style=\"padding:8px 12px;border:1px solid #e2e8f0;text-align:center;\">Gajah, Benteng</td>\n                        <td style=\"padding:8px 12px;border:1px solid #e2e8f0;text-align:center;\">Menang bidak di belakang</td>\n                    </tr>\n                </tbody>\n            </table>\n        </div>\n\n        <p class=\"text-gray-600 leading-relaxed text-sm mt-4\">\n            Ketiga pola taktis ini membentuk fondasi utama dari apa yang sering disebut sebagai \"penglihatan taktis\" — kemampuan untuk mengenali peluang keuntungan material dalam hitungan detik. Pemain yang terlatih tidak perlu menghitung setiap kemungkinan dari nol; mereka mengenali pola-pola ini secara intuitif karena telah menjumpainya ratusan kali dalam latihan dan permainan. Melatih pengenalan fork, pin, dan skewer melalui puzzle taktik secara konsisten adalah salah satu investasi waktu yang paling efisien bagi siapa pun yang ingin meningkatkan kekuatan bermainnya secara nyata dan terukur.\n        </p>\n    </div>"}]},{"id":"panduan-12","bab":"bab-dasar","nomor":"12","judul":"7 Kesalahan Umum Pemula dalam Catur dan Cara Menghindarinya","deskripsi":"Blunder atau kesalahan fatal adalah musuh terbesar pemain catur pemula. Pelajari tujuh kesalahan paling umum yang sering dilakukan pemula beserta cara menghindarinya agar rating catur kamu bisa naik lebih cepat.","baris":[{"sub":false,"html":"<div class=\"content-row\">\n        <div class=\"text-content\">\n            <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">Kesalahan Umum yang Sering Dilakukan Pemula dalam Catur</h3>\n            <p class=\"text-gray-600 leading-relaxed text-sm\">\n                Dalam catur, <em>blunder</em> adalah kesalahan besar yang mengubah evaluasi posisi secara drastis dalam satu langkah. Bentuknya bisa berupa kehilangan bidak tanpa kompensasi, membuka jalur skakmat yang seharusnya tertutup, atau memberikan lawan keunggulan posisi yang sangat sulit dipulihkan. Di level pemula, hasil permainan jauh lebih sering ditentukan oleh blunder semacam ini daripada oleh kualitas strategi yang dibangun. Karena itu, cara tercepat dan paling efisien untuk meningkatkan kekuatan bermain bukan dengan mencari langkah brilian, melainkan dengan secara konsisten mengurangi kesalahan fatal yang paling sering berulang.\n            </p>\n        </div>\n    </div>"},{"sub":true,"html":"<div class=\"content-row\" style=\"margin-top: 2rem; padding-top: 1.5rem; border-top: 2px dashed #e5e7eb;\">\n        <div class=\"board-panel relative\" style=\"float: right; margin-left: 1.5rem; margin-bottom: 1rem;\">\n            <svg viewBox=\"0 0 200 220\" class=\"w-full h-full\">\n                <rect width=\"200\" height=\"200\" fill=\"#769656\"/>\n                <g fill=\"#eeeed2\">\n                    <rect x=\"0\"   y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"100\" y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"150\" y=\"0\"   width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"125\" y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"175\" y=\"25\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"100\" y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"150\" y=\"50\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"125\" y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"175\" y=\"75\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"100\" width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"100\" width=\"25\" height=\"25\"/><rect x=\"100\" y=\"100\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"100\" width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"125\" width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"125\" width=\"25\" height=\"25\"/><rect x=\"125\" y=\"125\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"125\" width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"150\" width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"150\" width=\"25\" height=\"25\"/><rect x=\"100\" y=\"150\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"150\" width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"175\" width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"175\" width=\"25\" height=\"25\"/><rect x=\"125\" y=\"175\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"175\" width=\"25\" height=\"25\"/>\n                </g>\n                <defs>\n                    <marker id=\"arr-hang\" markerWidth=\"5\" markerHeight=\"5\" refX=\"4\" refY=\"2.5\" orient=\"auto\">\n                        <path d=\"M0,0 L5,2.5 L0,5 Z\" fill=\"#ef4444\"/>\n                    </marker>\n                </defs>\n                <!--\n                    Kuda putih d5 hanging — diserang Pion hitam c6 dan Gajah hitam e6\n                    Kuda putih  d5 → col=75,  row=75  → center (87.5,  87.5)\n                    Pion hitam  c6 → col=50,  row=50  → center (62.5,  62.5)\n                    Gajah hitam e6 → col=100, row=50  → center (112.5, 62.5)\n                    Tidak ada pelindung putih\n                -->\n                <!-- Highlight kuda hanging (merah mencolok) -->\n                <rect x=\"75\" y=\"75\" width=\"25\" height=\"25\" fill=\"#ef4444\" fill-opacity=\"0.55\"/>\n                <!-- Highlight penyerang 1: pion hitam c6 -->\n                <rect x=\"50\" y=\"50\" width=\"25\" height=\"25\" fill=\"#fbbf24\" fill-opacity=\"0.3\"/>\n                <!-- Highlight penyerang 2: gajah hitam e6 -->\n                <rect x=\"100\" y=\"50\" width=\"25\" height=\"25\" fill=\"#fbbf24\" fill-opacity=\"0.3\"/>\n                <!-- Panah pion c6 → d5 -->\n                <line x1=\"70\" y1=\"70\" x2=\"85\" y2=\"82\"\n                      stroke=\"#ef4444\" stroke-width=\"1.8\"\n                      stroke-dasharray=\"3,2\" marker-end=\"url(#arr-hang)\"/>\n                <!-- Panah gajah e6 → d5 -->\n                <line x1=\"105\" y1=\"70\" x2=\"98\" y2=\"82\"\n                      stroke=\"#ef4444\" stroke-width=\"1.8\"\n                      stroke-dasharray=\"3,2\" marker-end=\"url(#arr-hang)\"/>\n                <!-- Kuda putih d5 → (87.5, 87.5) -->\n                <text x=\"87.5\" y=\"87.5\" font-size=\"19\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\">♘</text>\n                <!-- Pion hitam c6 → (62.5, 62.5) -->\n                <text x=\"62.5\" y=\"62.5\" font-size=\"17\" fill=\"black\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\">♟</text>\n                <!-- Gajah hitam e6 → (112.5, 62.5) -->\n                <text x=\"112.5\" y=\"62.5\" font-size=\"17\" fill=\"black\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\">♝</text>\n                <!-- Badge HANGING -->\n                <rect x=\"68\" y=\"65\" width=\"40\" height=\"9\" rx=\"3\" fill=\"#7f1d1d\" fill-opacity=\"0.9\"/>\n                <text x=\"88\" y=\"70.5\" font-size=\"5\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\" font-weight=\"bold\">⚠ HANGING!</text>\n                <!-- Label koordinat -->\n                <text x=\"62.5\"  y=\"209\" font-size=\"6\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">c6</text>\n                <text x=\"87.5\"  y=\"209\" font-size=\"6\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">d5</text>\n                <text x=\"112.5\" y=\"209\" font-size=\"6\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">e6</text>\n                <text x=\"100\" y=\"218\" font-size=\"8\" fill=\"#7f1d1d\" text-anchor=\"middle\" font-weight=\"bold\">⚠ HANGING PIECE — Bidak Tanpa Perlindungan</text>\n            </svg>\n            <div style=\"display:flex; gap:6px; margin-top:4px; justify-content:center; flex-wrap:wrap;\">\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#ef4444;border-radius:2px;display:inline-block;opacity:0.7\"></span> Bidak hanging\n                </span>\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#fbbf24;border-radius:2px;display:inline-block;opacity:0.7\"></span> Penyerang\n                </span>\n            </div>\n        </div>\n        <div class=\"text-content\">\n            <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">① Meninggalkan Bidak Tanpa Perlindungan</h3>\n            <p class=\"text-gray-600 leading-relaxed text-sm\">\n                Kesalahan pertama dan paling umum di level pemula adalah membiarkan bidak dalam kondisi <em>hanging</em> — yaitu berada di kotak yang dapat ditangkap lawan secara gratis tanpa kompensasi apa pun. Seringkali kesalahan ini bukan karena pemain tidak tahu cara memainkan bidak tersebut, melainkan karena ia tidak melakukan pemeriksaan dasar sebelum menentukan langkah: apakah bidak yang dipindahkan benar-benar aman di kotak tujuannya?\n                <br><br>\n                Diagram di samping menggambarkan situasi yang sangat umum. Kuda putih baru saja dipindahkan ke <strong>d5</strong> — sebuah kotak yang terlihat aktif di pusat. Namun kuda tersebut diserang oleh pion hitam di <strong>c6</strong> dan gajah hitam di <strong>e6</strong>, sementara tidak ada satu pun bidak putih yang melindunginya. Siapapun yang mendapat giliran hitam berikutnya dapat mengambil kuda tersebut dengan bebas.\n                <br><br>\n                Solusi yang paling efektif untuk menghindari kesalahan ini adalah membiasakan diri dengan satu pertanyaan wajib sebelum setiap langkah: <em>\"Apakah bidak ini aman setelah saya pindahkan?\"</em> Hitung berapa kali bidak tersebut diserang dan berapa kali dilindungi. Jika jumlah penyerang melebihi pelindung, atau bidak sama sekali tidak terlindungi, langkah tersebut harus ditinjau ulang sebelum dimainkan. Kebiasaan pemeriksaan sederhana ini, jika dilakukan secara konsisten, mampu menghilangkan sebagian besar blunder material yang terjadi di level pemula.\n            </p>\n        </div>\n    </div>"},{"sub":true,"html":"<div class=\"content-row\" style=\"margin-top: 2rem; padding-top: 1.5rem; border-top: 2px dashed #e5e7eb;\">\n        <div class=\"board-panel relative\" style=\"float: left; margin-right: 1.5rem; margin-bottom: 1rem;\">\n            <svg viewBox=\"0 0 200 220\" class=\"w-full h-full\">\n                <rect width=\"200\" height=\"200\" fill=\"#769656\"/>\n                <g fill=\"#eeeed2\">\n                    <rect x=\"0\"   y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"100\" y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"150\" y=\"0\"   width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"125\" y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"175\" y=\"25\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"100\" y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"150\" y=\"50\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"125\" y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"175\" y=\"75\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"100\" width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"100\" width=\"25\" height=\"25\"/><rect x=\"100\" y=\"100\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"100\" width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"125\" width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"125\" width=\"25\" height=\"25\"/><rect x=\"125\" y=\"125\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"125\" width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"150\" width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"150\" width=\"25\" height=\"25\"/><rect x=\"100\" y=\"150\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"150\" width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"175\" width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"175\" width=\"25\" height=\"25\"/><rect x=\"125\" y=\"175\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"175\" width=\"25\" height=\"25\"/>\n                </g>\n                <defs>\n                    <marker id=\"arr-threat\" markerWidth=\"5\" markerHeight=\"5\" refX=\"4\" refY=\"2.5\" orient=\"auto\">\n                        <path d=\"M0,0 L5,2.5 L0,5 Z\" fill=\"#ef4444\"/>\n                    </marker>\n                </defs>\n                <!--\n                    Ratu hitam b4 mengancam Raja putih e1 dan Benteng putih e7 secara diagonal\n                    Ratu hitam  b4 → col=25,  row=100 → center (37.5,  112.5)\n                    Raja putih  e1 → col=100, row=175 → center (112.5, 187.5)\n                    Benteng putih e7 → col=100, row=25  → center (112.5, 37.5)\n                -->\n                <!-- Highlight ratu hitam b4 -->\n                <rect x=\"25\" y=\"100\" width=\"25\" height=\"25\" fill=\"#1e293b\" fill-opacity=\"0.45\"/>\n                <!-- Highlight raja putih e1 (diserang diagonal turun) -->\n                <rect x=\"100\" y=\"175\" width=\"25\" height=\"25\" fill=\"#ef4444\" fill-opacity=\"0.5\"/>\n                <!-- Highlight benteng putih e7 (diserang diagonal naik) -->\n                <rect x=\"100\" y=\"25\" width=\"25\" height=\"25\" fill=\"#f97316\" fill-opacity=\"0.4\"/>\n                \n                <!-- Jalur serangan ratu ke raja (b4 -> e1) -->\n                <line x1=\"48\" y1=\"123\" x2=\"100\" y2=\"175\"\n                      stroke=\"#ef4444\" stroke-width=\"1.8\" stroke-dasharray=\"3,2\"\n                      marker-end=\"url(#arr-threat)\"/>\n                \n                <!-- Jalur serangan ratu ke benteng (b4 -> e7) -->\n                <line x1=\"48\" y1=\"102\" x2=\"100\" y2=\"50\"\n                      stroke=\"#f97316\" stroke-width=\"1.8\" stroke-dasharray=\"3,2\"\n                      marker-end=\"url(#arr-threat)\"/>\n                      \n                <!-- Ratu hitam b4 → (37.5, 112.5) -->\n                <text x=\"37.5\" y=\"112.5\" font-size=\"19\" fill=\"black\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\">♛</text>\n                <!-- Raja putih e1 → (112.5, 187.5) -->\n                <text x=\"112.5\" y=\"187.5\" font-size=\"19\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\">♔</text>\n                <!-- Benteng putih e7 → (112.5, 37.5) -->\n                <text x=\"112.5\" y=\"37.5\" font-size=\"19\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\">♖</text>\n                \n                <!-- Badge ancaman di sebelah ratu -->\n                <rect x=\"4\" y=\"90\" width=\"43\" height=\"9\" rx=\"3\" fill=\"#7f1d1d\" fill-opacity=\"0.9\"/>\n                <text x=\"25.5\" y=\"95.5\" font-size=\"5\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\" font-weight=\"bold\">⚠ ANCAMAN GANDA!</text>\n                      \n                <!-- Label koordinat -->\n                <text x=\"37.5\"  y=\"209\" font-size=\"6\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">b4</text>\n                <text x=\"112.5\" y=\"209\" font-size=\"6\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">e-file</text>\n                <text x=\"100\" y=\"218\" font-size=\"8\" fill=\"#7f1d1d\" text-anchor=\"middle\" font-weight=\"bold\">⚠ ANCAMAN LAWAN DIABAIKAN</text>\n            </svg>\n            <div style=\"display:flex; gap:6px; margin-top:4px; justify-content:center; flex-wrap:wrap;\">\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#1e293b;border-radius:2px;display:inline-block;opacity:0.7\"></span> Ratu lawan\n                </span>\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#ef4444;border-radius:2px;display:inline-block;opacity:0.7\"></span> Target terancam\n                </span>\n            </div>\n        </div>\n        <div class=\"text-content\">\n            <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">② Tidak Melihat Ancaman Lawan</h3>\n            <p class=\"text-gray-600 leading-relaxed text-sm\">\n                Kesalahan kedua yang sangat umum adalah terlalu asyik merencanakan langkah sendiri hingga lupa bahwa lawan baru saja membuat ancaman yang membutuhkan respons segera. Pola ini sangat khas di level pemula: seorang pemain sudah memiliki rencana di kepalanya, lawan bergerak, dan tanpa memeriksa implikasi langkah terakhir tersebut, pemain langsung menjalankan rencana sebelumnya — sambil membiarkan ancaman lawan berkembang menjadi kenyataan yang menyakitkan.\n                <br><br>\n                Diagram di samping menggambarkan situasi yang sering diabaikan. Ratu hitam baru saja melangkah ke <strong>b4</strong> dan secara bersamaan memberikan ancaman ganda yang mematikan: ia mengancam raja putih di <strong>e1</strong> melalui diagonal turun (skak), dan di saat yang sama menyerang benteng putih di <strong>e7</strong> melalui diagonal naik. Karena benteng hanya bisa bergerak lurus, ia tidak bisa memakan ratu hitam tersebut. Ini adalah taktik <em>fork</em> oleh ratu yang mengharuskan putih merespons skak tersebut. Jika putih merespons dengan ceroboh (misalnya hanya memindahkan raja ke f1 tanpa mencoba melindungi benteng), benteng berharga di e7 pasti akan jatuh pada langkah berikutnya.\n                <br><br>\n                Kebiasaan yang paling penting untuk dibangun adalah menjadikan pertanyaan berikut sebagai refleks wajib setelah setiap langkah lawan: <em>\"Apa yang baru saja dilakukan lawan? Apa ancaman konkretnya? Apakah ada sesuatu yang terancam sekarang?\"</em> Hanya setelah pertanyaan-pertanyaan ini terjawab, pemain boleh melanjutkan rencananya sendiri — atau memodifikasinya sesuai kebutuhan. Disiplin sederhana ini adalah perbedaan terbesar antara pemain yang bermain reaktif secara sadar dan pemain yang sekadar merespons setelah sudah terlambat.\n            </p>\n        </div>\n    </div>"},{"sub":true,"html":"<div class=\"content-row\" style=\"margin-top: 2rem; padding-top: 1.5rem; border-top: 2px dashed #e5e7eb;\">\n        <div class=\"board-panel relative\" style=\"float: right; margin-left: 1.5rem; margin-bottom: 1rem;\">\n            <svg viewBox=\"0 0 200 220\" class=\"w-full h-full\">\n                <rect width=\"200\" height=\"200\" fill=\"#769656\"/>\n                <g fill=\"#eeeed2\">\n                    <rect x=\"0\"   y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"100\" y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"150\" y=\"0\"   width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"125\" y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"175\" y=\"25\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"100\" y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"150\" y=\"50\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"125\" y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"175\" y=\"75\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"100\" width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"100\" width=\"25\" height=\"25\"/><rect x=\"100\" y=\"100\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"100\" width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"125\" width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"125\" width=\"25\" height=\"25\"/><rect x=\"125\" y=\"125\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"125\" width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"150\" width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"150\" width=\"25\" height=\"25\"/><rect x=\"100\" y=\"150\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"150\" width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"175\" width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"175\" width=\"25\" height=\"25\"/><rect x=\"125\" y=\"175\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"175\" width=\"25\" height=\"25\"/>\n                </g>\n                <defs>\n                    <marker id=\"arr-queen\" markerWidth=\"5\" markerHeight=\"5\" refX=\"4\" refY=\"2.5\" orient=\"auto\">\n                        <path d=\"M0,0 L5,2.5 L0,5 Z\" fill=\"#ef4444\"/>\n                    </marker>\n                    <marker id=\"arr-queen-flee\" markerWidth=\"5\" markerHeight=\"5\" refX=\"4\" refY=\"2.5\" orient=\"auto\">\n                        <path d=\"M0,0 L5,2.5 L0,5 Z\" fill=\"#94a3b8\"/>\n                    </marker>\n                </defs>\n                <!--\n                    SKENARIO: Ratu putih d4 dikejar Kuda hitam c6\n                    Ratu putih  d4 → col=75, row=100 → center (87.5, 112.5)\n                    Kuda hitam  c6 → col=50, row=50  → center (62.5, 62.5)\n                -->\n                \n                <!-- Highlight ratu putih d4 (dalam bahaya) -->\n                <rect x=\"75\" y=\"100\" width=\"25\" height=\"25\" fill=\"#ef4444\" fill-opacity=\"0.45\"/>\n                \n                <!-- Highlight penyerang: Kuda hitam c6 -->\n                <rect x=\"50\" y=\"50\" width=\"25\" height=\"25\" fill=\"#22c55e\" fill-opacity=\"0.35\"/>\n                \n                <!-- Panah kuda c6 → mengusir ratu d4 -->\n                <line x1=\"68\" y1=\"73\" x2=\"82\" y2=\"101\"\n                      stroke=\"#ef4444\" stroke-width=\"1.8\" stroke-dasharray=\"3,2\"\n                      marker-end=\"url(#arr-queen)\"/>\n                      \n                <!-- Panah ratu kabur (mundur ke d1 atau e3) -->\n                <line x1=\"87.5\" y1=\"123\" x2=\"87.5\" y2=\"160\"\n                      stroke=\"#94a3b8\" stroke-width=\"1.8\" stroke-dasharray=\"2,2\"\n                      marker-end=\"url(#arr-queen-flee)\"/>\n\n                <!-- Ratu putih d4 → (87.5, 112.5) -->\n                <text x=\"87.5\" y=\"112.5\" font-size=\"19\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\">♕</text>\n                <!-- Kuda hitam c6 → (62.5, 62.5) -->\n                <text x=\"62.5\" y=\"62.5\" font-size=\"19\" fill=\"black\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\">♞</text>\n                      \n                <!-- Bidak pendukung konteks (Pion e4 putih) -->\n                <text x=\"112.5\" y=\"112.5\" font-size=\"15\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.6\">♙</text>\n\n                <!-- Badge tempo hilang -->\n                <rect x=\"52\" y=\"130\" width=\"45\" height=\"9\" rx=\"3\" fill=\"#7f1d1d\" fill-opacity=\"0.9\"/>\n                <text x=\"74.5\" y=\"135.5\" font-size=\"4.5\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\" font-weight=\"bold\">TEMPO HILANG ⏱</text>\n                      \n                <!-- Label koordinat -->\n                <text x=\"62.5\" y=\"209\" font-size=\"6\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">c6</text>\n                <text x=\"87.5\" y=\"209\" font-size=\"6\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">d4</text>\n                <text x=\"100\" y=\"218\" font-size=\"8\" fill=\"#7f1d1d\" text-anchor=\"middle\" font-weight=\"bold\">♕ RATU DIKEJAR — Kehilangan Giliran</text>\n            </svg>\n            <div style=\"display:flex; gap:6px; margin-top:4px; justify-content:center; flex-wrap:wrap;\">\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#ef4444;border-radius:2px;display:inline-block;opacity:0.7\"></span> Ratu terancam\n                </span>\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#22c55e;border-radius:2px;display:inline-block;opacity:0.7\"></span> Bidak musuh berkembang\n                </span>\n            </div>\n        </div>\n        <div class=\"text-content\">\n            <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">③ Mengeluarkan Ratu Terlalu Awal</h3>\n            <p class=\"text-gray-600 leading-relaxed text-sm\">\n                Ratu adalah bidak paling kuat dalam catur, dan justru karena alasan itulah ia seharusnya tidak dikeluarkan terlalu dini. Nilai ratu yang sangat tinggi menjadikannya sasaran empuk bagi bidak-bidak lawan yang bernilai lebih rendah. Setiap kali lawan mengancam ratu dengan kuda, gajah, atau pion, ratu terpaksa harus menghindar. Masalahnya: setiap kali ratu Anda mundur untuk menyelamatkan diri, sebuah giliran (tempo) berharga terbuang percuma.\n                <br><br>\n                Diagram di samping menampilkan contoh paling klasik dari kesalahan ini. Putih memakan pion di tengah menggunakan ratunya, menempatkan Ratu putih di <strong>d4</strong> secara prematur. Hitam dengan cerdas merespons dengan mengembangkan Kudanya ke <strong>c6</strong>, langsung menyerang ratu tersebut. \n                <br><br>\n                Perhatikan apa yang terjadi di sini: Hitam berhasil mengembangkan bidaknya (Kuda aktif ke tengah), sementara Putih sekarang *wajib* membuang gilirannya hanya untuk menarik Ratu mundur ke tempat yang aman. Putih tidak melakukan apa-apa selain menyelamatkan ratu, sedangkan posisi Hitam menjadi semakin kuat. Prinsip utamanya adalah: ratu seharusnya baru aktif ke tengah papan setelah bidak-bidak minor (kuda dan gajah) sudah berkembang dan posisi pertahanan sudah stabil.\n            </p>\n        </div>\n    </div>"},{"sub":true,"html":"<div class=\"content-row\" style=\"margin-top: 2rem; padding-top: 1.5rem; border-top: 2px dashed #e5e7eb;\">\n        <div class=\"board-panel relative\" style=\"float: left; margin-right: 1.5rem; margin-bottom: 1rem;\">\n            <svg viewBox=\"0 0 200 220\" class=\"w-full h-full\">\n                <rect width=\"200\" height=\"200\" fill=\"#769656\"/>\n                <g fill=\"#eeeed2\">\n                    <rect x=\"0\"   y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"100\" y=\"0\"   width=\"25\" height=\"25\"/><rect x=\"150\" y=\"0\"   width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"125\" y=\"25\"  width=\"25\" height=\"25\"/><rect x=\"175\" y=\"25\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"100\" y=\"50\"  width=\"25\" height=\"25\"/><rect x=\"150\" y=\"50\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"125\" y=\"75\"  width=\"25\" height=\"25\"/><rect x=\"175\" y=\"75\"  width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"100\" width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"100\" width=\"25\" height=\"25\"/><rect x=\"100\" y=\"100\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"100\" width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"125\" width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"125\" width=\"25\" height=\"25\"/><rect x=\"125\" y=\"125\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"125\" width=\"25\" height=\"25\"/>\n                    <rect x=\"0\"   y=\"150\" width=\"25\" height=\"25\"/><rect x=\"50\"  y=\"150\" width=\"25\" height=\"25\"/><rect x=\"100\" y=\"150\" width=\"25\" height=\"25\"/><rect x=\"150\" y=\"150\" width=\"25\" height=\"25\"/>\n                    <rect x=\"25\"  y=\"175\" width=\"25\" height=\"25\"/><rect x=\"75\"  y=\"175\" width=\"25\" height=\"25\"/><rect x=\"125\" y=\"175\" width=\"25\" height=\"25\"/><rect x=\"175\" y=\"175\" width=\"25\" height=\"25\"/>\n                </g>\n                <defs>\n                    <marker id=\"arr-sac\" markerWidth=\"5\" markerHeight=\"5\" refX=\"4\" refY=\"2.5\" orient=\"auto\">\n                        <path d=\"M0,0 L5,2.5 L0,5 Z\" fill=\"#ef4444\"/>\n                    </marker>\n                </defs>\n                <!--\n                    Gajah putih xh7+ sacrifice tanpa lanjutan (Greek Gift palsu)\n                    Gajah putih h7 → col=175, row=25  → center (187.5, 37.5)  [baru makan]\n                    Raja hitam  h8 → col=175, row=0   → center (187.5, 12.5)\n                    Kuda putih  f3 → col=125, row=125 → center (137.5, 137.5) [jauh, tidak mendukung]\n                    Ratu putih  d1 → col=75,  row=175 → center (87.5,  187.5) [jauh]\n                -->\n                <!-- Highlight gajah putih di h7 (sacrifice) -->\n                <rect x=\"175\" y=\"25\" width=\"25\" height=\"25\" fill=\"#ef4444\" fill-opacity=\"0.45\"/>\n                <!-- Highlight raja hitam h8 -->\n                <rect x=\"175\" y=\"0\" width=\"25\" height=\"25\" fill=\"#374151\" fill-opacity=\"0.5\"/>\n                <!-- Garis tanda tanya besar -->\n                <rect x=\"80\" y=\"80\" width=\"40\" height=\"40\" rx=\"6\" fill=\"#fef3c7\" stroke=\"#f59e0b\" stroke-width=\"1.5\" fill-opacity=\"0.9\"/>\n                <text x=\"100\" y=\"100\" font-size=\"24\" text-anchor=\"middle\" dominant-baseline=\"central\" fill=\"#92400e\" font-weight=\"bold\">?</text>\n                <!-- Gajah putih di h7 → (187.5, 37.5) -->\n                <text x=\"187.5\" y=\"37.5\" font-size=\"17\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\">♗</text>\n                <!-- Raja hitam h8 → (187.5, 12.5) -->\n                <text x=\"187.5\" y=\"12.5\" font-size=\"17\" fill=\"black\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\">♚</text>\n                <!-- Kuda putih f3 (jauh, tidak mendukung) → (137.5, 137.5) -->\n                <text x=\"137.5\" y=\"137.5\" font-size=\"15\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.5\">♘</text>\n                <!-- Ratu putih d1 (jauh) → (87.5, 187.5) -->\n                <text x=\"87.5\" y=\"187.5\" font-size=\"15\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\" opacity=\"0.5\">♕</text>\n                <!-- Label \"tidak ada lanjutan\" -->\n                <rect x=\"145\" y=\"45\" width=\"52\" height=\"9\" rx=\"3\" fill=\"#92400e\" fill-opacity=\"0.85\"/>\n                <text x=\"171\" y=\"50.5\" font-size=\"4.5\" fill=\"white\"\n                      text-anchor=\"middle\" dominant-baseline=\"central\" font-weight=\"bold\">Tidak ada lanjutan!</text>\n                <!-- Label bidak jauh -->\n                <text x=\"125\" y=\"150\" font-size=\"5\" fill=\"#94a3b8\" text-anchor=\"middle\">♘ jauh</text>\n                <text x=\"75\" y=\"200\" font-size=\"5\" fill=\"#94a3b8\" text-anchor=\"middle\">♕ jauh</text>\n                <!-- Label koordinat -->\n                <text x=\"137.5\" y=\"209\" font-size=\"6\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">f3</text>\n                <text x=\"187.5\" y=\"209\" font-size=\"6\" fill=\"#374151\" text-anchor=\"middle\" font-weight=\"bold\">h7</text>\n                <text x=\"100\" y=\"218\" font-size=\"8\" fill=\"#92400e\" text-anchor=\"middle\" font-weight=\"bold\">? SACRIFICE TANPA KALKULASI</text>\n            </svg>\n            <div style=\"display:flex; gap:6px; margin-top:4px; justify-content:center; flex-wrap:wrap;\">\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#ef4444;border-radius:2px;display:inline-block;opacity:0.7\"></span> Sacrifice terburu-buru\n                </span>\n                <span style=\"display:flex;align-items:center;gap:3px;font-size:8px;color:#555;\">\n                    <span style=\"width:8px;height:8px;background:#fbbf24;border-radius:2px;display:inline-block;opacity:0.7\"></span> Tidak ada lanjutan\n                </span>\n            </div>\n        </div>\n        <div class=\"text-content\">\n            <h3 class=\"text-xl font-extrabold text-chess-green uppercase mb-3 leading-tight\">④ Mengorbankan Bidak Tanpa Kalkulasi</h3>\n            <p class=\"text-gray-600 leading-relaxed text-sm\">\n                Pengorbanan bidak atau <em>sacrifice</em> adalah salah satu aspek catur yang paling dramatis dan paling mengesankan ketika dilakukan dengan benar. Namun di tangan pemula yang belum memiliki kemampuan kalkulasi yang cukup, sacrifice sering kali berubah menjadi blunder yang terlihat agresif — kehilangan material tanpa mendapat kompensasi yang sepadan. Motivasi di baliknya biasanya bukan perhitungan yang matang, melainkan dorongan impulsif untuk menyerang karena posisi terlihat menjanjikan secara visual.\n                <br><br>\n                Diagram di samping menggambarkan situasi <em>Greek Gift</em> palsu yang sangat umum. Gajah putih mengorbankan diri di <strong>h7</strong> untuk menyerang raja hitam di <strong>h8</strong>, sebuah pola serangan terkenal. Namun dalam posisi ini, kuda putih masih jauh di f3 dan ratu putih masih di d1 — tidak ada bidak putih lain yang siap melanjutkan serangan. Raja hitam bisa bertahan, dan putih hanya kehilangan gajah tanpa mendapat apa-apa.\n                <br><br>\n                Prinsip yang harus dipegang teguh adalah: sacrifice hanya sah dilakukan ketika ada lanjutan konkret yang dapat dihitung sampai akhir — baik berupa serangan langsung ke raja, pemulihan material, maupun keuntungan posisi yang terukur. Jika setelah berkorban tidak ada rencana yang jelas tentang apa yang terjadi tiga atau empat langkah ke depan, hampir dapat dipastikan bahwa sacrifice tersebut hanyalah blunder dalam kemasan yang dramatis.\n            </p>\n        </div>\n    </div>"},{"sub":true,"html":"<div style=\"margin-top: 2rem; padding-top: 1.5rem; border-top: 2px dashed #e5e7eb;\">\n        <h3 class=\"text-lg font-extrabold text-chess-green uppercase mb-4 leading-tight\">Tiga Kesalahan Lainnya yang Sama Berbahayanya</h3>\n\n        <!-- Baris tiga kartu -->\n        <div style=\"display:flex; gap:1rem; flex-wrap:wrap;\">\n\n            <!-- KESALAHAN 5: Scholar's Mate -->\n            <div style=\"flex:1; min-width:180px; border:1px solid #e5e7eb; border-radius:8px; overflow:hidden;\">\n                <div style=\"background:#fef2f2; padding:10px 12px; border-bottom:1px solid #fecaca;\">\n                    <p style=\"font-size:11px; font-weight:800; color:#991b1b; margin:0; text-transform:uppercase;\">⑤ Terjebak Scholar's Mate</p>\n                </div>\n                <div style=\"padding:10px 12px;\">\n                    <svg viewBox=\"0 0 120 80\" style=\"width:100%;margin-bottom:6px;\">\n                        <rect width=\"120\" height=\"80\" fill=\"#769656\"/>\n                        <g fill=\"#eeeed2\">\n                            <rect x=\"0\" y=\"0\" width=\"15\" height=\"15\"/><rect x=\"30\" y=\"0\" width=\"15\" height=\"15\"/><rect x=\"60\" y=\"0\" width=\"15\" height=\"15\"/><rect x=\"90\" y=\"0\" width=\"15\" height=\"15\"/>\n                            <rect x=\"15\" y=\"15\" width=\"15\" height=\"15\"/><rect x=\"45\" y=\"15\" width=\"15\" height=\"15\"/><rect x=\"75\" y=\"15\" width=\"15\" height=\"15\"/><rect x=\"105\" y=\"15\" width=\"15\" height=\"15\"/>\n                            <rect x=\"0\" y=\"30\" width=\"15\" height=\"15\"/><rect x=\"30\" y=\"30\" width=\"15\" height=\"15\"/><rect x=\"60\" y=\"30\" width=\"15\" height=\"15\"/><rect x=\"90\" y=\"30\" width=\"15\" height=\"15\"/>\n                            <rect x=\"15\" y=\"45\" width=\"15\" height=\"15\"/><rect x=\"45\" y=\"45\" width=\"15\" height=\"15\"/><rect x=\"75\" y=\"45\" width=\"15\" height=\"15\"/><rect x=\"105\" y=\"45\" width=\"15\" height=\"15\"/>\n                            <rect x=\"0\" y=\"60\" width=\"15\" height=\"15\"/><rect x=\"30\" y=\"60\" width=\"15\" height=\"15\"/><rect x=\"60\" y=\"60\" width=\"15\" height=\"15\"/><rect x=\"90\" y=\"60\" width=\"15\" height=\"15\"/>\n                            <rect x=\"15\" y=\"75\" width=\"15\" height=\"15\"/><rect x=\"45\" y=\"75\" width=\"15\" height=\"15\"/><rect x=\"75\" y=\"75\" width=\"15\" height=\"15\"/><rect x=\"105\" y=\"75\" width=\"15\" height=\"15\"/>\n                        </g>\n                        <!-- f7 target merah (col f=75px di papan 120px→ col=5*15=75, row 7=15) -->\n                        <!-- Scale: 120/8=15px per kotak. col: a=0,b=15,c=30,d=45,e=60,f=75,g=90,h=105; row: 8=0,7=15,6=30,5=45,4=60,3=75-->\n                        <rect x=\"75\" y=\"15\" width=\"15\" height=\"15\" fill=\"#ef4444\" fill-opacity=\"0.6\"/>\n                        <!-- Raja hitam e8 (60,0) -->\n                        <text x=\"67.5\" y=\"7.5\" font-size=\"11\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\">♚</text>\n                        <!-- Ratu putih h5 (105,45) -->\n                        <text x=\"112.5\" y=\"52.5\" font-size=\"11\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♕</text>\n                        <!-- Gajah putih c4 (30,60) -->\n                        <text x=\"37.5\" y=\"67.5\" font-size=\"11\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♗</text>\n                        <!-- Panah ke f7 -->\n                        <line x1=\"108\" y1=\"49\" x2=\"83\" y2=\"21\" stroke=\"#ef4444\" stroke-width=\"1.2\" stroke-dasharray=\"2,1\" marker-end=\"url(#arr-sm)\"/>\n                        <line x1=\"40\" y1=\"63\" x2=\"80\" y2=\"21\" stroke=\"#f97316\" stroke-width=\"1.2\" stroke-dasharray=\"2,1\" marker-end=\"url(#arr-sm)\"/>\n                        <defs><marker id=\"arr-sm\" markerWidth=\"4\" markerHeight=\"4\" refX=\"3\" refY=\"2\" orient=\"auto\"><path d=\"M0,0 L4,2 L0,4 Z\" fill=\"#ef4444\"/></marker></defs>\n                        <text x=\"82.5\" y=\"23\" font-size=\"5\" fill=\"white\" text-anchor=\"middle\" font-weight=\"bold\">f7!</text>\n                    </svg>\n                    <p style=\"font-size:11px;color:#4b5563;line-height:1.5;margin:0;\">\n                        Titik <strong>f7</strong> hanya dijaga raja sejak awal. Kombinasi Qh5 + Bc4 menciptakan ancaman skakmat yang sangat cepat. Respons yang tepat adalah <strong>...Nf6</strong> untuk mengusir ratu, atau <strong>...g6</strong> untuk menutup diagonal serangan.\n                    </p>\n                </div>\n            </div>\n\n                        <!-- KESALAHAN 6: Back Rank Mate (SECTION 12 - REVISI) -->\n            <div style=\"flex:1; min-width:180px; border:1px solid #e5e7eb; border-radius:8px; overflow:hidden;\">\n                <div style=\"background:#fef2f2; padding:10px 12px; border-bottom:1px solid #fecaca;\">\n                    <p style=\"font-size:11px; font-weight:800; color:#991b1b; margin:0; text-transform:uppercase;\">⑥ Terkena Back Rank Mate</p>\n                </div>\n                <div style=\"padding:10px 12px;\">\n                    <svg viewBox=\"0 0 120 80\" style=\"width:100%;margin-bottom:6px;\">\n                        <rect width=\"120\" height=\"80\" fill=\"#769656\"/>\n                        <g fill=\"#eeeed2\">\n                            <rect x=\"0\" y=\"0\" width=\"15\" height=\"15\"/><rect x=\"30\" y=\"0\" width=\"15\" height=\"15\"/><rect x=\"60\" y=\"0\" width=\"15\" height=\"15\"/><rect x=\"90\" y=\"0\" width=\"15\" height=\"15\"/>\n                            <rect x=\"15\" y=\"15\" width=\"15\" height=\"15\"/><rect x=\"45\" y=\"15\" width=\"15\" height=\"15\"/><rect x=\"75\" y=\"15\" width=\"15\" height=\"15\"/><rect x=\"105\" y=\"15\" width=\"15\" height=\"15\"/>\n                            <rect x=\"0\" y=\"30\" width=\"15\" height=\"15\"/><rect x=\"30\" y=\"30\" width=\"15\" height=\"15\"/><rect x=\"60\" y=\"30\" width=\"15\" height=\"15\"/><rect x=\"90\" y=\"30\" width=\"15\" height=\"15\"/>\n                            <rect x=\"15\" y=\"45\" width=\"15\" height=\"15\"/><rect x=\"45\" y=\"45\" width=\"15\" height=\"15\"/><rect x=\"75\" y=\"45\" width=\"15\" height=\"15\"/><rect x=\"105\" y=\"45\" width=\"15\" height=\"15\"/>\n                            <rect x=\"0\" y=\"60\" width=\"15\" height=\"15\"/><rect x=\"30\" y=\"60\" width=\"15\" height=\"15\"/><rect x=\"60\" y=\"60\" width=\"15\" height=\"15\"/><rect x=\"90\" y=\"60\" width=\"15\" height=\"15\"/>\n                            <rect x=\"15\" y=\"75\" width=\"15\" height=\"15\"/><rect x=\"45\" y=\"75\" width=\"15\" height=\"15\"/><rect x=\"75\" y=\"75\" width=\"15\" height=\"15\"/><rect x=\"105\" y=\"75\" width=\"15\" height=\"15\"/>\n                        </g>\n                        <!-- Skala: 15px per kotak. Col e=60, f=75, g=90, h=105 -->\n                        <!-- Raja hitam g8 (90,0) -->\n                        <rect x=\"90\" y=\"0\" width=\"15\" height=\"15\" fill=\"#ef4444\" fill-opacity=\"0.5\"/>\n                        <text x=\"97.5\" y=\"7.5\" font-size=\"11\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\">♚</text>\n                        <!-- Pion hitam f7, g7, h7 -->\n                        <text x=\"82.5\" y=\"22.5\" font-size=\"10\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\">♟</text>\n                        <text x=\"97.5\" y=\"22.5\" font-size=\"10\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\">♟</text>\n                        <text x=\"112.5\" y=\"22.5\" font-size=\"10\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\">♟</text>\n                        \n                        <!-- Benteng putih masuk dari kolom e yang terbuka mendarat di e8 (60,0) -->\n                        <rect x=\"60\" y=\"0\" width=\"15\" height=\"15\" fill=\"#0284c7\" fill-opacity=\"0.3\"/>\n                        <text x=\"67.5\" y=\"7.5\" font-size=\"11\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♖</text>\n                        \n                        <!-- Panah Benteng naik (biru) -->\n                        <line x1=\"67.5\" y1=\"65\" x2=\"67.5\" y2=\"15\" stroke=\"#0284c7\" stroke-width=\"1.2\" stroke-dasharray=\"2,2\" opacity=\"0.6\"/>\n                        <!-- Panah Skak horizontal (merah) -->\n                        <line x1=\"75\" y1=\"7.5\" x2=\"88\" y2=\"7.5\" stroke=\"#ef4444\" stroke-width=\"1.2\" marker-end=\"url(#arr-sm)\"/>\n                        \n                        <!-- Luft -->\n                        <rect x=\"105\" y=\"30\" width=\"15\" height=\"15\" fill=\"#22c55e\" fill-opacity=\"0.4\"/>\n                        <text x=\"112.5\" y=\"37.5\" font-size=\"6\" fill=\"#15803d\" text-anchor=\"middle\" dominant-baseline=\"central\" font-weight=\"bold\">luft</text>\n                    </svg>\n                    <p style=\"font-size:11px;color:#4b5563;line-height:1.5;margin:0;\">\n                        Pion pelindung raja justru menjadi penjara. Benteng putih masuk baris belakang melalui <strong>kolom yang terbuka (e)</strong> dan skakmat horizontal. Solusinya: buat <strong>luft</strong> (...h6).\n                    </p>\n                </div>\n            </div>\n\n            <!-- KESALAHAN 7: Stalemate -->\n            <div style=\"flex:1; min-width:180px; border:1px solid #e5e7eb; border-radius:8px; overflow:hidden;\">\n                <div style=\"background:#fefce8; padding:10px 12px; border-bottom:1px solid #fde68a;\">\n                    <p style=\"font-size:11px; font-weight:800; color:#92400e; margin:0; text-transform:uppercase;\">⑦ Membuat Stalemate saat Unggul</p>\n                </div>\n                <div style=\"padding:10px 12px;\">\n                    <svg viewBox=\"0 0 120 80\" style=\"width:100%;margin-bottom:6px;\">\n                        <rect width=\"120\" height=\"80\" fill=\"#769656\"/>\n                        <g fill=\"#eeeed2\">\n                            <rect x=\"0\" y=\"0\" width=\"15\" height=\"15\"/><rect x=\"30\" y=\"0\" width=\"15\" height=\"15\"/><rect x=\"60\" y=\"0\" width=\"15\" height=\"15\"/><rect x=\"90\" y=\"0\" width=\"15\" height=\"15\"/>\n                            <rect x=\"15\" y=\"15\" width=\"15\" height=\"15\"/><rect x=\"45\" y=\"15\" width=\"15\" height=\"15\"/><rect x=\"75\" y=\"15\" width=\"15\" height=\"15\"/><rect x=\"105\" y=\"15\" width=\"15\" height=\"15\"/>\n                            <rect x=\"0\" y=\"30\" width=\"15\" height=\"15\"/><rect x=\"30\" y=\"30\" width=\"15\" height=\"15\"/><rect x=\"60\" y=\"30\" width=\"15\" height=\"15\"/><rect x=\"90\" y=\"30\" width=\"15\" height=\"15\"/>\n                            <rect x=\"15\" y=\"45\" width=\"15\" height=\"15\"/><rect x=\"45\" y=\"45\" width=\"15\" height=\"15\"/><rect x=\"75\" y=\"45\" width=\"15\" height=\"15\"/><rect x=\"105\" y=\"45\" width=\"15\" height=\"15\"/>\n                            <rect x=\"0\" y=\"60\" width=\"15\" height=\"15\"/><rect x=\"30\" y=\"60\" width=\"15\" height=\"15\"/><rect x=\"60\" y=\"60\" width=\"15\" height=\"15\"/><rect x=\"90\" y=\"60\" width=\"15\" height=\"15\"/>\n                            <rect x=\"15\" y=\"75\" width=\"15\" height=\"15\"/><rect x=\"45\" y=\"75\" width=\"15\" height=\"15\"/><rect x=\"75\" y=\"75\" width=\"15\" height=\"15\"/><rect x=\"105\" y=\"75\" width=\"15\" height=\"15\"/>\n                        </g>\n                        <!-- Raja hitam a8 (0,0) — tidak diserang tapi tidak bisa gerak -->\n                        <rect x=\"0\" y=\"0\" width=\"15\" height=\"15\" fill=\"#f59e0b\" fill-opacity=\"0.55\"/>\n                        <text x=\"7.5\" y=\"7.5\" font-size=\"11\" fill=\"black\" text-anchor=\"middle\" dominant-baseline=\"central\">♚</text>\n                        <!-- Ratu putih b6 (15,30) mengontrol a7,b7,b8 -->\n                        <rect x=\"15\" y=\"30\" width=\"15\" height=\"15\" fill=\"#8b5cf6\" fill-opacity=\"0.3\"/>\n                        <text x=\"22.5\" y=\"37.5\" font-size=\"11\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♕</text>\n                        <!-- Raja putih c7 (30,15) -->\n                        <rect x=\"30\" y=\"15\" width=\"15\" height=\"15\" fill=\"#8b5cf6\" fill-opacity=\"0.2\"/>\n                        <text x=\"37.5\" y=\"22.5\" font-size=\"11\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\">♔</text>\n                        <!-- Kotak tertutup a7(0,15), b7(15,15), b8(15,0) -->\n                        <g stroke=\"#dc2626\" stroke-width=\"1.2\" opacity=\"0.7\">\n                            <line x1=\"2\" y1=\"17\" x2=\"13\" y2=\"28\"/><line x1=\"13\" y1=\"17\" x2=\"2\" y2=\"28\"/>\n                            <line x1=\"17\" y1=\"17\" x2=\"28\" y2=\"28\"/><line x1=\"28\" y1=\"17\" x2=\"17\" y2=\"28\"/>\n                            <line x1=\"17\" y1=\"2\" x2=\"28\" y2=\"13\"/><line x1=\"28\" y1=\"2\" x2=\"17\" y2=\"13\"/>\n                        </g>\n                        <!-- Badge SERI -->\n                        <rect x=\"45\" y=\"28\" width=\"30\" height=\"12\" rx=\"3\" fill=\"#d97706\" fill-opacity=\"0.9\"/>\n                        <text x=\"60\" y=\"35\" font-size=\"7\" fill=\"white\" text-anchor=\"middle\" dominant-baseline=\"central\" font-weight=\"bold\">= SERI!</text>\n                    </svg>\n                    <p style=\"font-size:11px;color:#4b5563;line-height:1.5;margin:0;\">\n                        Raja hitam tidak diserang tetapi tidak punya langkah legal — hasilnya <strong>remis</strong>, bukan kemenangan. Selalu pastikan raja lawan punya setidaknya <strong>satu langkah legal</strong> sebelum langkah akhir.\n                    </p>\n                </div>\n            </div>\n\n        </div><!-- end flex kartu -->\n    </div>"},{"sub":true,"html":"<div style=\"margin-top: 2rem; padding-top: 1.5rem; border-top: 2px dashed #e5e7eb;\">\n        <h3 class=\"text-lg font-extrabold text-chess-green uppercase mb-3 leading-tight\">📌 Prinsip Akhir: Stabil Lebih Baik dari Brilian</h3>\n        <p class=\"text-gray-600 leading-relaxed text-sm\">\n            Menghindari ketujuh kesalahan yang telah diuraikan ini akan memberikan dampak yang jauh lebih besar terhadap hasil permainan dibandingkan menghafal teori pembukaan yang rumit atau mempelajari kombinasi taktis yang panjang. Di level pemula, pertandingan hampir selalu diputuskan oleh siapa yang lebih sedikit membuat blunder — bukan oleh siapa yang memiliki rencana paling canggih. Pemain yang secara konsisten menjaga bidaknya tetap terlindungi, memeriksa ancaman lawan sebelum bergerak, dan tidak memberikan kemenangan gratis melalui kesalahan dasar, akan hampir selalu unggul atas lawan yang bermain lebih agresif tetapi kurang cermat.\n            <br><br>\n            Stabilitas dan kehati-hatian adalah fondasi pertama dari permainan yang kuat. Kecemerlangan taktis akan datang dengan sendirinya seiring bertambahnya pengalaman dan pemahaman posisional — tetapi tanpa fondasi yang solid berupa minimnya blunder dasar, kemampuan taktis secanggih apa pun akan terus dirusak oleh kesalahan yang seharusnya sudah tidak terjadi.\n        </p>\n    </div>"}]}];
